import{O as t}from"./main-0iNMT0tK.js";import"./vendor-react-OE2f6Nbm.js";import"./vendor-other-rCQIOS6m.js";import"./vendor-leaflet-Bjm2FGmM.js";import"./core-astro-AwPpBXFF.js";import"./core-data-BzebUjTq.js";import"./vendor-utils-C0M50lIz.js";const a=[{id:"pj1",title:"दैनिक पूजा विधि",tags:["पूजा","विधि","धर्म"],content:[{type:"heading",text:"बिहानी नित्य कर्म"},{type:"paragraph",text:"बिहान ब्रह्म मुहूर्तमा (सूर्योदय अघि ४८ मिनेट) उठ्नु उत्तम हो। उठेपछि भूमिलाई प्रणाम गर्दै यो श्लोक पढ्नुपर्छ:"},{type:"verse",text:`समुद्रवसने देवि पर्वतस्तनमण्डले।
विष्णुपत्नि नमस्तुभ्यं पादस्पर्शं क्षमस्व मे॥`,translation:"हे समुद्ररूपी वस्त्र धारण गर्ने, पर्वतरूपी स्तन भएकी, विष्णुपत्नी धर्ती माता! तपाईंलाई नमस्कार, मेरो पाउको स्पर्श क्षमा गर्नुहोस्।"},{type:"image",src:t.dailyPuja,alt:"Daily Puja",caption:"दैनिक पूजा"},{type:"heading",text:"शुद्धि र स्नान"},{type:"paragraph",text:'दातुन (दन्त मञ्जन) गरी शौच विधि पूरा गर्ने। त्यसपछि <span class="text-orange-600 font-bold">शुद्ध जलले स्नान</span> गर्ने। स्नान गर्दा यो मन्त्र भन्ने:'},{type:"verse",text:`गङ्गे च यमुने चैव गोदावरि सरस्वति।
नर्मदे सिन्धु कावेरि जलेऽस्मिन् सन्निधिं कुरु॥`,translation:"हे गंगा, यमुना, गोदावरी, सरस्वती, नर्मदा, सिन्धु र कावेरी! यस जलमा तपाईंहरूको सान्निध्य होस्।"},{type:"heading",text:"आचमन विधि"},{type:"paragraph",text:"शुद्ध वस्त्र धारण गरेपछि आचमन गर्नुपर्छ। दायाँ हातको तलुवामा जल लिएर तीन पटक पिउने:"},{type:"list",items:['पहिलो आचमन: "ॐ केशवाय नमः" भन्दै','दोस्रो आचमन: "ॐ नारायणाय नमः" भन्दै','तेस्रो आचमन: "ॐ माधवाय नमः" भन्दै']},{type:"heading",text:"सङ्कल्प"},{type:"paragraph",text:"पूजा गर्नुअघि सङ्कल्प लिनु अत्यन्त आवश्यक छ। दायाँ हातमा अक्षता, फूल र जल लिएर आफूले कुन पूजा, कुन देवताको, कुन उद्देश्यले गर्दैछौं भनेर बोल्ने। सामान्य सङ्कल्प:"},{type:"verse",text:`ॐ विष्णुर्विष्णुर्विष्णुः। अद्य शुभतिथौ...
मम सकुटुम्बस्य क्षेमस्थैर्यायुरारोग्यैश्वर्याभिवृद्ध्यर्थं
श्री[कुलदेवता]प्रीत्यर्थं पूजनमहं करिष्ये।`},{type:"heading",text:"पूजा गर्ने क्रम (षोडशोपचार)"},{type:"list",items:["१. आवाहन — देवतालाई बोलाउने","२. आसन — बस्ने ठाउँ दिने","३. पाद्य — पाउ धुने जल","४. अर्घ्य — हात धुने जल","५. आचमनीय — मुख शुद्ध गर्ने जल","६. स्नान — अभिषेक","७. वस्त्र — लुगा चढाउने","८. यज्ञोपवीत — जनै चढाउने","९. गन्ध — चन्दन लगाउने","१०. अक्षता — अक्षता (चामल) चढाउने","११. पुष्प — फूल चढाउने","१२. धूप — धूप बाल्ने","१३. दीप — दियो बाल्ने","१४. नैवेद्य — खानेकुरा (भोग) चढाउने","१५. ताम्बूल — सुपारी, लौंग चढाउने","१६. प्रदक्षिणा र नमस्कार — परिक्रमा गरी ढोग्ने"]},{type:"heading",text:"आरती र प्रसाद"},{type:"paragraph",text:"पूजाको अन्त्यमा घिउ वा कर्पूरले आरती गरिन्छ। आरती गर्दा घण्टी बजाउने र मन्त्र भन्ने। आरती पछि प्रसाद वितरण गर्ने। प्रसाद सधैं दायाँ हातले लिने र ग्रहण गर्ने।"},{type:"paragraph",text:"<strong>नोट:</strong> पूजा गर्दा मन शुद्ध र एकाग्र हुनुपर्छ। बाह्य विधिभन्दा भावना (भक्ति) नै प्रमुख हो।"}]},{id:"pj2",title:"गणेश पूजा",tags:["पूजा","धर्म","पौराणिक"],content:[{type:"paragraph",text:"सबैभन्दा पहिले गणेशको पूजा गरिन्छ। गणेशलाई विघ्नहर्ता (बाधा हटाउने) मानिन्छ। कुनै पनि शुभ कार्य, पूजा वा यज्ञ गर्नुअघि गणेश पूजा अनिवार्य मानिन्छ।"},{type:"heading",text:"गणेशजीको महत्व"},{type:"paragraph",text:"गणेश भगवान शिव र पार्वतीका पुत्र हुन्। उहाँलाई बुद्धि, विद्या र सिद्धिका देवता मानिन्छ। मंगलमूर्ति, लम्बोदर, एकदन्त, विनायक — यी सबै गणेशका नाम हुन्। उहाँको वाहन मूसा (मूषक) हो, जसले अहंकारलाई वशमा राख्ने शक्ति दर्शाउँछ।"},{type:"heading",text:"आवश्यक सामग्री"},{type:"list",items:["दुबो (दूर्वा) — गणेशलाई सबैभन्दा प्रिय","अक्षता (चामल) र सिन्दूर","लड्डु वा मोदक (नैवेद्य)","रातो फूल, रातो वस्त्र","सुपारी, नरिवल","चन्दन, कुमकुम, अगरबत्ती","घिउको दियो र कर्पूर"]},{type:"heading",text:"गणेश पूजा विधि"},{type:"list",items:["१. शुद्ध स्थानमा रातो वस्त्र बिछ्याएर गणेश मूर्ति वा तस्बिर राख्ने।","२. दियो बाल्ने र अगरबत्ती जगाउने।","३. कलश स्थापना गर्ने — ताम्रपात्रमा जल, आम्रपत्र र नरिवल राख्ने।","४. गणेशजीलाई जलले अभिषेक गर्ने।","५. सिन्दूर र चन्दन लगाउने।","६. दुबो र रातो फूल चढाउने (दुबोको २१ गाँठा चढाउनु उत्तम)।","७. लड्डु वा मोदक नैवेद्य चढाउने।","८. गणेश मन्त्र जपः"]},{type:"verse",text:"ॐ गं गणपतये नमः",translation:"गणपतिलाई नमस्कार। यो मन्त्र १०८ पटक जप्ने।"},{type:"heading",text:"गणेश अथर्वशीर्ष (सारांश)"},{type:"verse",text:`ॐ नमस्ते गणपतये।
त्वमेव प्रत्यक्षं तत्त्वमसि।
त्वमेव केवलं कर्तासि।
त्वमेव केवलं धर्तासि।
त्वमेव केवलं हर्तासि।
त्वमेव सर्वं खल्विदं ब्रह्मासि।`,translation:"हे गणपति! तपाईं नै प्रत्यक्ष तत्त्व हुनुहुन्छ। तपाईं नै एकमात्र कर्ता, धारणकर्ता र संहारकर्ता हुनुहुन्छ। तपाईं नै यो सम्पूर्ण ब्रह्म हुनुहुन्छ।"},{type:"heading",text:"विशेष तिथि"},{type:"paragraph",text:"<strong>गणेश चतुर्थी</strong> (भाद्र शुक्ल चतुर्थी) गणेश पूजाको सबैभन्दा प्रमुख तिथि हो। यसका अतिरिक्त प्रत्येक महिनाको शुक्ल चतुर्थी (विनायक चतुर्थी) र कृष्ण चतुर्थी (संकष्टी चतुर्थी) मा गणेश पूजा गर्ने चलन छ। मंगलबार पनि गणेशको विशेष दिन मानिन्छ।"}]},{id:"pj3",title:"शिव पूजा",tags:["पूजा","धर्म","पौराणिक"],content:[{type:"paragraph",text:'सोमबार शिवको विशेष दिन हो। शिवजीलाई भोलेनाथ, महादेव, शंकर, त्रिलोचन, नीलकण्ठ आदि नामहरूले चिनिन्छ। उहाँ संहारका देवता भए पनि भक्तहरूलाई सजिलै प्रसन्न हुनुहुन्छ, त्यसैले उहाँलाई "आशुतोष" पनि भनिन्छ।'},{type:"image",src:t.shivaLingam,alt:"Shiva Lingam"},{type:"heading",text:"शिवलिङ्गको महत्व"},{type:"paragraph",text:'शिवलिङ्ग भगवान शिवको निराकार स्वरूपको प्रतीक हो। यो ब्रह्माण्डको उत्पत्ति र विलयको शक्तिलाई जनाउँछ। लिङ्ग शब्दको अर्थ "चिन्ह" वा "प्रतीक" हो, जसले निराकार परमेश्वरको अस्तित्वलाई दर्शाउँछ।'},{type:"heading",text:"चढाउने वस्तुहरू"},{type:"list",items:["बेलपत्र — त्रिदल (तीन पातको) बेलपत्र शिवलाई अत्यन्त प्रिय छ। यसले त्रिगुण (सत्व, रजस्, तमस्) को अर्पण जनाउँछ।","जल (गंगाजल) — शिवलाई अभिषेक गर्नु विशेष पुण्यदायक मानिन्छ।","दूध — क्षीराभिषेक (दूधले अभिषेक) मोक्षदायक मानिन्छ।","दही — शत्रु नाशको लागि।","घिउ — सौभाग्य र समृद्धिको लागि।","मह — वाणी मधुर हुनको लागि।","चिनी/सखर — दुःख नाशको लागि।","धतुरो — शिवजीको प्रिय फूल। अन्य देवतालाई चढाइँदैन।","भाङ — शिवको तपस्या र वैराग्यको प्रतीक।","अक्षता (चामल) — चढाउनु हुँदैन (शिवलिङ्गमा)। गणेश र पार्वतीलाई चढाउने।"]},{type:"heading",text:"रुद्राभिषेक विधि"},{type:"paragraph",text:"रुद्राभिषेक शिवको सबैभन्दा शक्तिशाली पूजा मानिन्छ। यसमा रुद्रम् (श्री रुद्रम्) को पाठ गर्दै शिवलिङ्गमा पञ्चामृत (दूध, दही, घिउ, मह, चिनी) ले अभिषेक गरिन्छ।"},{type:"list",items:["१. शुद्ध स्थानमा शिवलिङ्ग वा मूर्ति स्थापना गर्ने।",'२. "ॐ नमः शिवाय" भन्दै जलाभिषेक गर्ने।',"३. पञ्चामृतले अभिषेक — एक-एक गर्दै मन्त्र भन्ने।","४. पुनः शुद्ध जलले धुने।","५. बेलपत्र, धतुरो, आँक र सेतो फूल चढाउने।","६. भस्म (विभूति) लगाउने।",'७. "ॐ नमः शिवाय" मन्त्र १०८ पटक जप्ने।',"८. शिव चालिसा वा शिव ताण्डव स्तोत्र पाठ गर्ने।","९. आरती गरी प्रसाद वितरण गर्ने।"]},{type:"heading",text:"शिव पूजाको उत्तम समय"},{type:"paragraph",text:"<strong>प्रदोष काल</strong> (सूर्यास्तपछिको ४५ मिनेट) शिव पूजाको सर्वोत्तम समय मानिन्छ। विशेष गरी त्रयोदशी तिथिको प्रदोष काल (प्रदोष व्रत) मा शिवपूजा अत्यन्त फलदायक हुन्छ। सोमबार र साउने सोमबार शिवको विशेष दिन हो। <strong>महाशिवरात्रि</strong> (फागुन कृष्ण चतुर्दशी) शिव पूजाको सबैभन्दा महत्वपूर्ण दिन हो।"}]},{id:"pj4",title:"सरस्वती पूजा",tags:["पूजा","चाडपर्व","संस्कृति"],content:[{type:"heading",text:"श्रीपञ्चमी"},{type:"paragraph",text:"श्रीपञ्चमी वा वसन्त पञ्चमीको दिन विद्याकी देवी सरस्वतीको पूजा गरिन्छ। विद्यार्थीहरूका लागि यो विशेष दिन हो। सरस्वती माता ज्ञान, संगीत, कला र वाणीकी अधिष्ठात्री देवी हुनुहुन्छ।"},{type:"heading",text:"पूजा विधि"},{type:"list",items:["बिहान सबेरै उठेर स्नान गर्ने।","सरस्वतीको प्रतिमा वा पुस्तक, कापी, कलम सफा कपडामा राख्ने।","पहेँलो फूल, अक्षता, चन्दन र नैवेद्य चढाउने।","सरस्वती बन्दना पाठ गर्ने।","बालबालिकाहरूलाई यसै दिन अक्षर आरम्भ (विद्यारम्भ) गराउने परम्परा छ।"]},{type:"verse",text:`या कुन्देन्दुतुषारहारधवला या शुभ्रवस्त्रावृता
या वीणावरदण्डमण्डितकरा या श्वेतपद्मासना।
या ब्रह्माच्युतशंकरप्रभृतिभिर्देवैः सदा वन्दिता
सा मां पातु सरस्वती भगवती निःशेषजाड्यापहा॥`,translation:"कुन्दको फूल, चन्द्रमा र हिउँ जस्तै गोरो, सेतो वस्त्र धारण गर्ने, वीणा हातमा भएकी, सेतो कमलमा विराजमान, ब्रह्मा-विष्णु-शिवले पूजन गर्ने, ती अज्ञानता हटाउने सरस्वती मेरो रक्षा गरून्।"}]},{id:"pj5",title:"लक्ष्मी पूजा",tags:["पूजा","चाडपर्व","संस्कृति"],content:[{type:"heading",text:"दीपावली"},{type:"paragraph",text:"तिहारको औंसीको रात धनकी देवी लक्ष्मीको पूजा गरिन्छ। यस दिन घरलाई झिलिमिली बत्तीले सजाइन्छ। लक्ष्मी माता सम्पत्ति, सौभाग्य, ऐश्वर्य र समृद्धिकी देवी हुनुहुन्छ।"},{type:"heading",text:"तयारी र विधि"},{type:"list",items:["घर आँगन सफा गरी गाईको गोबर वा रातो माटोले लिप्ने।","मूल ढोकामा सयपत्री फूलको माला र बत्ती बाल्ने।","घरको भित्री कोठासम्म लक्ष्मीको पाइला बनाउने।","दियो, कलश र गणेशको पूजा गरी लक्ष्मी माताको आह्वान गर्ने।","कमलको फूल, रातो वस्त्र, धूप-दीप चढाउने।","लक्ष्मी सहस्रनाम वा श्री सूक्तम् पाठ गर्ने।"]},{type:"verse",text:`ॐ श्रीं ह्रीं श्रीं कमले कमलालये प्रसीद प्रसीद।
ॐ श्रीं ह्रीं श्रीं महालक्ष्म्यै नमः॥`,translation:"लक्ष्मी बीज मन्त्र: कमलमा निवास गर्ने महालक्ष्मीलाई नमस्कार।"},{type:"paragraph",text:"<strong>विशेष:</strong> लक्ष्मी पूजा प्रदोष काल (साँझ) मा गर्नु उत्तम मानिन्छ। शुक्रबार लक्ष्मीको विशेष दिन हो। कोजाग्रत पूर्णिमा (अश्विन पूर्णिमा) मा पनि लक्ष्मी पूजा गरिन्छ।"}]},{id:"pj6",title:"हनुमान पूजा विधि",tags:["पूजा","धर्म","शक्ति"],content:[{type:"paragraph",text:"महावीर हनुमान बल, बुद्धि र विद्याका खानी हुन्। उहाँ भगवान रामका परम भक्त र शिवको ११औँ रुद्र अवतार मानिन्छन्। मंगलबार र शनिबार हनुमान पूजाका विशेष दिन हुन्।"},{type:"heading",text:"हनुमान पूजाको महत्व"},{type:"list",items:["भय, रोग र शत्रुबाट मुक्ति","शनि ग्रहको दोष शान्त हुन्छ","साहस, आत्मविश्वास र शक्ति बढ्छ","नकारात्मक शक्ति र बुरी नजरबाट रक्षा","मुकद्दमा र विवादमा विजय"]},{type:"heading",text:"पूजा विधि"},{type:"list",items:["१. बिहान उठेर स्नान गर्ने। रातो वा केसरी रंगको वस्त्र लगाउने।","२. हनुमान मन्दिर वा घरमा हनुमानको तस्बिर अगाडि बस्ने।","३. तेल र सिन्दूर मिसाएर हनुमानजीलाई लगाउने। (यो सबैभन्दा प्रिय चढावा हो।)","४. रातो फूलको माला चढाउने।","५. लड्डु (बेसन वा बुन्दीको) नैवेद्य चढाउने।","६. हनुमान चालिसा पाठ गर्ने।",'७. "ॐ हं हनुमते नमः" वा "ॐ हं हनुमते रुद्रात्मकाय हुं फट्" मन्त्र जप गर्ने।',"८. बजरंग बाण पाठ (विशेष कष्ट भएमा)।","९. प्रदक्षिणा गरी नमस्कार गर्ने।"]},{type:"verse",text:`मनोजवं मारुततुल्यवेगं जितेन्द्रियं बुद्धिमतां वरिष्ठम्।
वातात्मजं वानरयूथमुख्यं श्रीरामदूतं शरणं प्रपद्ये॥`,translation:"मनको गतिले चल्ने, वायु जस्तो वेग भएका, इन्द्रियहरूलाई जित्ने, बुद्धिमानहरूमा श्रेष्ठ, पवनपुत्र, वानरसेनाका मुखिया, श्रीरामका दूत हनुमानको शरणमा म जान्छु।"},{type:"paragraph",text:"<strong>विशेष:</strong> शनिबार सरसों (तोरी) को तेल र सिन्दूर चढाउँदा शनि दोष शान्त हुन्छ। हनुमान जयन्ती (चैत्र पूर्णिमा) मा विशेष पूजा गरिन्छ।"}]},{id:"pj7",title:"सत्यनारायण व्रत कथा",tags:["पूजा","व्रत","विधि"],content:[{type:"paragraph",text:"सत्यनारायण व्रत हिन्दू धर्मको सबैभन्दा लोकप्रिय र सरल व्रत हो। यो व्रत पूर्णिमा, एकादशी वा कुनै शुभ अवसरमा गरिन्छ। नयाँ घर, विवाह, जन्मोत्सव वा मनोकामना पूर्तिपछि यो पूजा गर्ने चलन छ।"},{type:"heading",text:"आवश्यक सामग्री"},{type:"list",items:["पञ्चामृत (दूध, दही, घिउ, मह, चिनी)","गहुँको आटा र चिनी मिसाएको प्रसाद (शीरा/प्रशाद)","केरा, सुपारी, नरिवल, तुलसीपत्र","हरियो दुबो, फूल, अक्षता","रातो कपडा, कलश, आमको पात","घिउको दियो र अगरबत्ती","सत्यनारायण व्रत कथा पुस्तक"]},{type:"heading",text:"पूजा विधि (संक्षेपमा)"},{type:"list",items:["१. शुद्ध स्थानमा कलश स्थापना गर्ने। कलशमाथि नरिवल राख्ने।","२. गणेश पूजा गर्ने (विघ्न नाशको लागि)।","३. नवग्रह र कुलदेवताको पूजा गर्ने।","४. भगवान विष्णुको (सत्यनारायणको) आह्वान गर्ने।",'५. "ॐ नमो भगवते वासुदेवाय" मन्त्र जप गर्ने।',"६. सत्यनारायण कथा (५ अध्याय) पढ्ने वा सुन्ने।","७. आरती गर्ने र प्रसाद वितरण गर्ने।"]},{type:"heading",text:"कथाको सारांश"},{type:"paragraph",text:"<strong>अध्याय १:</strong> नारदजीले विष्णुभगवानलाई कलियुगमा मानिसहरूको दुःख हटाउने उपाय सोध्नुभयो। भगवानले सत्यनारायण व्रतको विधि बताउनुभयो।"},{type:"paragraph",text:"<strong>अध्याय २:</strong> एक गरिब ब्राह्मणले यो व्रत गरेर धन-सम्पत्ति पायो। एक काठ बेच्ने व्यापारीले पनि यो व्रत गरेर सफलता पायो।"},{type:"paragraph",text:"<strong>अध्याय ३:</strong> राजा उल्कामुख र उनकी रानीको कथा — व्रत गर्ने प्रतिज्ञा गरेर पनि नगर्दा कष्ट भोग्नुपर्यो।"},{type:"paragraph",text:"<strong>अध्याय ४:</strong> साधु वैश्य (व्यापारी) ले व्रत गरेर समृद्धि पाए, तर प्रसाद नखाएर कष्ट पाए।"},{type:"paragraph",text:"<strong>अध्याय ५:</strong> साधु वैश्यकी छोरी कलावतीले प्रसाद नलिएर पतिलाई गुमाइन्, पछि प्रसाद लिएपछि सबै ठिक भयो। <strong>शिक्षा:</strong> प्रसाद सधैं ग्रहण गर्नुपर्छ।"}]},{id:"pj8",title:"नवग्रह पूजा विधि",tags:["पूजा","ज्योतिष","विधि"],content:[{type:"paragraph",text:"नवग्रह (नौ ग्रह) को पूजाले ग्रह दोष शान्त हुन्छ र जीवनमा शान्ति आउँछ। सूर्य, चन्द्र, मंगल, बुध, बृहस्पति, शुक्र, शनि, राहु र केतु — यी नै नवग्रह हुन्।"},{type:"heading",text:"प्रत्येक ग्रहको विवरण"},{type:"list",items:["सूर्य (आइतबार): रातो फूल, गहुँ, गुड, रातो वस्त्र। मन्त्र: ॐ ह्रां ह्रीं ह्रौं सः सूर्याय नमः","चन्द्र (सोमबार): सेतो फूल, चामल, दूध, सेतो वस्त्र। मन्त्र: ॐ श्रां श्रीं श्रौं सः चन्द्रमसे नमः","मंगल (मंगलबार): रातो फूल, मसुर दाल, गुड, रातो वस्त्र। मन्त्र: ॐ क्रां क्रीं क्रौं सः भौमाय नमः","बुध (बुधबार): हरियो फूल, मुगको दाल, हरियो वस्त्र। मन्त्र: ॐ ब्रां ब्रीं ब्रौं सः बुधाय नमः","बृहस्पति (बिहीबार): पहेँलो फूल, चना दाल, हल्दी, पहेँलो वस्त्र। मन्त्र: ॐ ग्रां ग्रीं ग्रौं सः गुरवे नमः","शुक्र (शुक्रबार): सेतो फूल, चामल, खिर, सेतो वस्त्र। मन्त्र: ॐ द्रां द्रीं द्रौं सः शुक्राय नमः","शनि (शनिबार): कालो/नीलो फूल, कालो तिल, तेल, कालो वस्त्र। मन्त्र: ॐ प्रां प्रीं प्रौं सः शनैश्चराय नमः","राहु: नीलो वस्त्र, उड्दको दाल। मन्त्र: ॐ भ्रां भ्रीं भ्रौं सः राहवे नमः","केतु: भुरो (खैरो) वस्त्र, कुल्थी दाल। मन्त्र: ॐ स्रां स्रीं स्रौं सः केतवे नमः"]},{type:"heading",text:"सरल पूजा विधि"},{type:"list",items:["१. नवग्रह यन्त्र वा तस्बिर राख्ने।","२. प्रत्येक ग्रहलाई सम्बन्धित रंगको फूल चढाउने।","३. प्रत्येक ग्रहको मन्त्र ७ पटक वा १०८ पटक जप गर्ने।","४. सम्बन्धित दिनमा सम्बन्धित ग्रहको पूजा विशेष फलदायी हुन्छ।","५. दान-दक्षिणा गर्ने (ग्रह अनुसार)।"]},{type:"paragraph",text:"<strong>नोट:</strong> गम्भीर ग्रह दोषको लागि विद्वान् ज्योतिषी (पण्डित) को परामर्श लिनुपर्छ। यो सामान्य पूजा दैनिक शान्ति र सुरक्षाको लागि हो।"}]},{id:"pj9",title:"तुलसी पूजा विधि",tags:["पूजा","दैनिक","प्रकृति"],content:[{type:"paragraph",text:"तुलसी (Holy Basil) हिन्दू धर्ममा सबैभन्दा पवित्र बिरुवा मानिन्छ। तुलसीलाई भगवान विष्णुकी पत्नी (लक्ष्मीको अवतार) को रूपमा पूजा गरिन्छ। घरमा तुलसी भएको ठाउँमा लक्ष्मी निवास गर्नुहुन्छ भन्ने विश्वास छ।"},{type:"heading",text:"वैज्ञानिक महत्व"},{type:"list",items:["तुलसीले हावामा अक्सिजन छोड्छ र कीटाणुनाशक गुण राख्छ।","तुलसीको पानीले रोगप्रतिरोधक क्षमता (Immunity) बढाउँछ।","रुघा, खोकी, ज्वरो जस्ता रोगमा तुलसी गुणकारी छ।","तुलसीको बोट नजिकै मच्छर र कीटपतंग आउँदैनन्।"]},{type:"heading",text:"दैनिक तुलसी पूजा"},{type:"list",items:["१. साँझको समयमा (सूर्यास्तको आसपास) तुलसी पूजा गर्ने चलन छ।","२. तुलसीको बिरुवाको गमलामा दियो (दीप) बाल्ने।","३. तुलसीको जरामा जल चढाउने।","४. अक्षता, रातो सिन्दूर र हल्दी चढाउने।","५. तुलसी मन्त्र वा परिक्रमा (घुम्ने) गर्ने।"]},{type:"verse",text:`तुलसी श्रीसखी शुभे पापहारिणी पुण्यदे।
नमस्ते नारदनुते नारायणमनःप्रिये॥`,translation:"हे तुलसी! हजुर लक्ष्मीकी सखी, शुभकारिणी, पापनाशिनी, पुण्यदायिनी, नारदद्वारा स्तुत र नारायणलाई प्रिय हुनुहुन्छ। हजुरलाई नमस्कार।"},{type:"heading",text:"तुलसी विवाह"},{type:"paragraph",text:"<strong>कार्तिक शुक्ल एकादशी</strong> (देवोत्थान एकादशी) को दिन तुलसी विवाह गरिन्छ। तुलसीको बिरुवासँग शालिग्राम (विष्णुको स्वरूप) को विवाह कराइन्छ। यो दिनपछि हिन्दू विवाहको सिजन सुरु हुन्छ।"}]},{id:"pj10",title:"दुर्गा पूजा विधि",tags:["पूजा","नवरात्रि","शक्ति"],content:[{type:"paragraph",text:"देवी दुर्गा शक्तिकी स्वरूप हुनुहुन्छ। नवरात्रि (अश्विन शुक्ल प्रतिपदा देखि नवमी सम्म) मा दुर्गा पूजा विशेष रूपमा गरिन्छ। नेपालमा यो समय दशैं (बडा दशैँ) को रूपमा मनाइन्छ।"},{type:"heading",text:"नवदुर्गा — ९ दिन ९ रूप"},{type:"list",items:["प्रतिपदा: शैलपुत्री — पर्वतराज हिमालयकी पुत्री","द्वितीया: ब्रह्मचारिणी — तपस्या र जपको स्वरूप","तृतीया: चन्द्रघण्टा — शिरमा चन्द्रमाको आकार भएकी","चतुर्थी: कूष्माण्डा — ब्रह्माण्ड सृजना गर्ने शक्ति","पञ्चमी: स्कन्दमाता — कार्तिकेयकी माता","षष्ठी: कात्यायनी — महर्षि कात्यायनकी पुत्री","सप्तमी: कालरात्रि — कालको पनि नाश गर्ने","अष्टमी: महागौरी — अत्यन्त गोरो र सुन्दर रूप","नवमी: सिद्धिदात्री — सबै प्रकारको सिद्धि दिने"]},{type:"heading",text:"घटस्थापना (कलश स्थापना)"},{type:"paragraph",text:"नवरात्रिको पहिलो दिन (प्रतिपदा) मा घटस्थापना गरिन्छ। मट्टिकोमा जौँ (जमरा) छरिन्छ र कलशमाथि नरिवल राखी दुर्गा माताको आह्वान गरिन्छ। ९ दिनसम्म दियो नबुझ्ने गरी अखण्ड ज्योति बाल्ने चलन छ।"},{type:"heading",text:"पूजा विधि"},{type:"list",items:["१. स्नान गरी शुद्ध वस्त्र (रातो वा गुलाबी) लगाउने।","२. दुर्गा माताको मूर्ति वा तस्बिर अगाडि दियो बाल्ने।","३. रातो फूल (विशेष गरी हिबिस्कस), सिन्दूर, चन्दन चढाउने।","४. दुर्गा सप्तशती (देवी महात्म्य/चण्डीपाठ) को पाठ गर्ने।",'५. "ॐ दुं दुर्गायै नमः" मन्त्र जप गर्ने।',"६. अष्टमी वा नवमीमा कन्या पूजन (कुमारी पूजा) गर्ने।","७. हवन (होम) गर्ने।","८. दशमीमा (विजया दशमी) टीका र जमरा लगाउने।"]},{type:"verse",text:`सर्वमंगलमांगल्ये शिवे सर्वार्थसाधिके।
शरण्ये त्र्यम्बके गौरि नारायणि नमोऽस्तु ते॥`,translation:"हे सबै मंगलहरूकी मंगलमयी, कल्याणदायिनी, सबै कामना पूर्ण गर्ने, शरणयोग्य, तीन नेत्र भएकी गौरी, नारायणी! तपाईंलाई नमस्कार छ।"},{type:"paragraph",text:"<strong>विशेष:</strong> चैत्र नवरात्रि (वासन्तिक) र अश्विन नवरात्रि (शारदीय) — वर्षमा दुई पटक प्रमुख नवरात्रि आउँछ। दशैँ अश्विन नवरात्रिसँगै जोडिएको छ।"}]}],p=[{id:"m1",title:"गायत्री मन्त्र",subtitle:"बुद्धि र विवेकको लागि",tags:["मन्त्र","धर्म","ध्यान"],content:[{type:"heading",text:"मूल मन्त्र"},{type:"verse",text:`ॐ भूर्भुवः स्वः तत्सवितुर्वरेण्यं
भर्गो देवस्य धीमहि
धियो यो नः प्रचोदयात्॥`,translation:"ती प्राणस्वरूप, दुःखनाशक, सुखस्वरूप, श्रेष्ठ, तेजस्वी, पापनाशक, देवस्वरूप परमात्मालाई हामी अन्तःकरणमा धारण गरौं। ती परमात्माले हाम्रो बुद्धिलाई सन्मार्गमा प्रेरित गरून्।"},{type:"heading",text:"जप विधि"},{type:"paragraph",text:"गायत्री मन्त्र <strong>सन्ध्या कालमा</strong> (बिहान सूर्योदय, मध्यान्ह र साँझ सूर्यास्त) जप गर्नु सर्वोत्तम मानिन्छ। एक पटकमा <strong>१०८ पटक</strong> (एक माला) जप गर्ने। रुद्राक्ष वा चन्दनको मालाले जप गर्नु उत्तम हो।"},{type:"heading",text:"लाभहरू"},{type:"list",items:["बुद्धि तीव्र र विवेकशील हुन्छ।","एकाग्रता र स्मरणशक्ति बढ्छ।","नकारात्मक विचार र मानसिक तनाव कम हुन्छ।","आध्यात्मिक उन्नति र आत्मशुद्धि हुन्छ।",'वेदहरूमा यसलाई "मन्त्रहरूकी माता" भनिएको छ।']},{type:"paragraph",text:"<strong>विशेष:</strong> उपनयन (ब्रतबन्ध) संस्कारमा गुरुले शिष्यलाई सबैभन्दा पहिले गायत्री मन्त्र दिनुहुन्छ। यो वैदिक संस्कृतिको सबैभन्दा प्राचीन र पवित्र मन्त्र हो।"}]},{id:"m2",title:"महामृत्युञ्जय मन्त्र",subtitle:"स्वास्थ्य र दीर्घायुको लागि",tags:["मन्त्र","धर्म","स्वास्थ्य"],content:[{type:"heading",text:"मूल मन्त्र"},{type:"verse",text:`ॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्।
उर्वारुकमिव बन्धनान् मृत्योर्मुक्षीय मामृतात्॥`,translation:"हामी ती तीन नेत्र भएका (शिव) को पूजा गर्छौं जसले सुगन्ध फैलाउँछन् र पोषण दिन्छन्। जसरी पाकेको काँक्रो बोटबाट आफैं अलग हुन्छ, त्यसरी नै हामीलाई मृत्युको बन्धनबाट मुक्त गरी अमरत्व (मोक्ष) प्रदान गर्नुहोस्।"},{type:"heading",text:"जप विधि"},{type:"paragraph",text:"यो मन्त्र <strong>रुद्राक्षको माला</strong>मा जप गर्नुपर्छ। एक पटकमा <strong>१०८ पटक</strong> वा ११ पटक जप गर्ने। बिरामी व्यक्तिको लागि जप गर्दा बिरामीको नाम लिएर सङ्कल्प गर्ने। जन्मदिन (जन्म तिथि) मा यो मन्त्रको विशेष जप गरिन्छ।"},{type:"heading",text:"कहिले जप गर्ने?"},{type:"list",items:["गम्भीर बिरामीको आरोग्यको लागि","दीर्घायु र स्वास्थ्यको लागि","अकालमृत्यु (Accidental death) बाट रक्षाको लागि","जन्मदिनमा आयुको आशीर्वाद प्राप्त गर्न","महामृत्युञ्जय जप (१,२५,००० पटक) ले गम्भीर दोष शान्त हुन्छ"]},{type:"paragraph",text:"यो मन्त्र ऋग्वेदको सातौं मण्डलमा ऋषि मार्कण्डेयद्वारा उच्चारण गरिएको छ। ऋषि मार्कण्डेयले यसै मन्त्रको बलमा यमराजलाई पनि जितेका थिए।"}]},{id:"m3",title:"गणेश मन्त्र",subtitle:"विघ्न नाश र सफलताको लागि",tags:["मन्त्र","धर्म","सफलता"],content:[{type:"heading",text:"मूल श्लोक"},{type:"verse",text:`वक्रतुण्ड महाकाय सूर्यकोटि समप्रभ।
निर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा॥`,translation:"बाङ्गो सुँड भएका, विशाल शरीर भएका, करोडौं सूर्य समान तेज भएका हे गणेश देव! मेरा सम्पूर्ण कार्यहरूमा सधैं विघ्न बाधा हटाईदिनुहोस्।"},{type:"heading",text:"बीज मन्त्र"},{type:"verse",text:"ॐ गं गणपतये नमः",translation:'"गं" गणेशको बीज अक्षर हो। यो मन्त्र १०८ पटक जप गर्नुपर्छ।'},{type:"heading",text:"जप विधि र समय"},{type:"list",items:["मंगलबार र चतुर्थी तिथिमा जप विशेष फलदायक।","नयाँ कार्य सुरु गर्नुअघि २१ पटक जप गर्ने।","परीक्षा, अन्तर्वार्ता वा ठूलो काम अघि स्मरण गर्ने।","हल्दी वा रातो चन्दनको मालाले जप उत्तम।","दुबो (दूर्वा) हातमा लिएर जप गर्दा विशेष फल मिल्छ।"]},{type:"paragraph",text:"<strong>विशेष:</strong> गणेश अथर्वशीर्ष (उपनिषद्) को पाठ गर्दा विद्या, बुद्धि र सम्पत्ति प्राप्त हुन्छ। संकष्टी चतुर्थी (कृष्ण पक्ष चतुर्थी) मा व्रत बसेर गणेश पूजा गर्दा सबै संकटबाट मुक्ति मिल्छ।"}]},{id:"m4",title:"सरस्वती वन्दना",subtitle:"विद्या र ज्ञानको लागि",tags:["मन्त्र","धर्म","शिक्षा"],content:[{type:"heading",text:"श्लोक"},{type:"verse",text:`या कुन्देन्दुतुषारहारधवला या शुभ्रवस्त्रावृता
या वीणावरदण्डमण्डितकरा या श्वेतपद्मासना।
या ब्रह्माच्युतशंकरप्रभृतिभिर्देवैः सदा वन्दिता
सा मां पातु सरस्वती भगवती निःशेषजाड्यापहा॥`,translation:"जो कुन्दको फूल, चन्द्रमा र हिउँ जस्तै सेतो हुनुहुन्छ, जसले सेतो वस्त्र धारण गर्नुभएको छ, जसको हातमा वीणा सोभायमान छ, जो सेतो कमलको फूलमा विराजमान हुनुहुन्छ, जसलाई ब्रह्मा, विष्णु र महेश आदि देवताहरूले सधैं पूजा गर्छन्, ती अज्ञानता हटाउने सरस्वती माताले मेरो रक्षा गरून्।"},{type:"heading",text:"बीज मन्त्र"},{type:"verse",text:"ॐ ऐं सरस्वत्यै नमः",translation:'"ऐं" सरस्वतीको बीज अक्षर हो। विद्या र वाणीको सिद्धिको लागि यो मन्त्र जप गरिन्छ।'},{type:"heading",text:"जप विधि"},{type:"list",items:["बिहान सूर्योदयको समयमा पूर्वमुख फर्केर बस्ने।","स्फटिक (Crystal) वा सेतो चन्दनको मालामा जप गर्ने।","१०८ पटक जप गर्ने। विद्यार्थीहरूले दैनिक ११ पटक भने पनि जप गर्नु फलदायक।","श्रीपञ्चमी (वसन्त पञ्चमी) मा विशेष जप गर्ने।","पुस्तक, कलम वा बाजाको अगाडि बसेर जप गर्दा विद्या वा कला सिद्ध हुन्छ।"]},{type:"paragraph",text:"यो वन्दना विशेष गरी परीक्षा वा अध्ययनको समयमा जप गरिन्छ। सरस्वतीले ज्ञान, स्मरणशक्ति र वाक् सिद्धि प्रदान गर्नुहुन्छ।"}]},{id:"m5",title:"गुरु मन्त्र",subtitle:"गुरु प्रति सम्मान",tags:["मन्त्र","धर्म","सम्मान"],content:[{type:"heading",text:"श्लोक"},{type:"verse",text:`गुरुर्ब्रह्मा गुरुर्विष्णुः गुरुर्देवो महेश्वरः।
गुरुः साक्षात् परब्रह्म तस्मै श्रीगुरवे नमः॥`,translation:"गुरु नै ब्रह्मा हुनुहुन्छ, गुरु नै विष्णु हुनुहुन्छ, र गुरु नै भगवान शिव हुनुहुन्छ। गुरु नै साक्षात परब्रह्म (परमात्मा) हुनुहुन्छ। त्यस्ता सद्गुरुलाई म प्रणाम गर्दछु।"},{type:"heading",text:"अन्य गुरु श्लोक"},{type:"verse",text:`अखण्डमण्डलाकारं व्याप्तं येन चराचरम्।
तत्पदं दर्शितं येन तस्मै श्रीगुरवे नमः॥`,translation:"जसले अखण्ड मण्डलाकार (ब्रह्माण्ड) मा व्याप्त चराचर (जीवित र निर्जीव) को तत्त्वलाई दर्शन गराउनुभयो, त्यस्ता सद्गुरुलाई नमस्कार।"},{type:"heading",text:"कहिले जप गर्ने?"},{type:"list",items:["गुरु पूर्णिमा (आषाढ/असार पूर्णिमा) मा विशेष पूजा र जप।","बिहीबार गुरुको विशेष दिन हो।","अध्ययन वा साधना सुरु गर्नुअघि गुरु स्मरण गर्ने।","दीक्षा (Initiation) लिएपछि गुरुले दिनुभएको मन्त्रको नित्य जप गर्ने।"]},{type:"paragraph",text:"यो मन्त्र गुरु पूजाको क्रममा वा गुरुको स्मरण गर्दा जप गरिन्छ। भारतीय-नेपाली परम्परामा गुरुको स्थान भगवानभन्दा पनि माथि मानिन्छ।"}]},{id:"m6",title:"शान्ति मन्त्र",subtitle:"विश्व शान्ति की कामना",tags:["मन्त्र","धर्म","शान्ति"],content:[{type:"heading",text:"वैदिक मन्त्र"},{type:"verse",text:`ॐ सर्वे भवन्तु सुखिनः सर्वे सन्तु निरामयाः।
सर्वे भद्राणि पश्यन्तु मा कश्चित् दुःखभागभवेत्॥
ॐ शान्तिः शान्तिः शान्तिः॥`,translation:"सबै सुखी होउन्, सबै रोगमुक्त (निरोगी) होउन्। सबैले कल्याण देख्न पाउन्, कसैले पनि दुःख भोग्न नपरोस्। ॐ शान्ति, शान्ति, शान्ति।"},{type:"heading",text:"अन्य शान्ति मन्त्र"},{type:"verse",text:`ॐ असतो मा सद्गमय।
तमसो मा ज्योतिर्गमय।
मृत्योर्मामृतं गमय।
ॐ शान्तिः शान्तिः शान्तिः॥`,translation:"असत्यबाट सत्यतिर, अन्धकारबाट उज्यालो तिर, मृत्यूबाट अमरत्व तिर लैजानुहोस्। ॐ शान्ति, शान्ति, शान्ति।"},{type:"heading",text:"तीन पटक शान्ति किन?"},{type:"paragraph",text:'शान्ति तीन पटक भन्नुको विशेष अर्थ छ: पहिलो <strong>"शान्तिः"</strong> — आधिदैविक (प्राकृतिक विपत्ति, भूकम्प, बाढी आदि) ताप शान्त होस्। दोस्रो <strong>"शान्तिः"</strong> — आधिभौतिक (अन्य प्राणीहरूबाट आउने कष्ट) ताप शान्त होस्। तेस्रो <strong>"शान्तिः"</strong> — आध्यात्मिक (मन र शरीरको रोग) ताप शान्त होस्।'},{type:"paragraph",text:"यो मन्त्र विश्व शान्ति र समृद्धिको लागि जप गरिन्छ। प्रत्येक वैदिक पूजा, यज्ञ र हवनको अन्त्यमा शान्ति पाठ गरिन्छ।"}]},{id:"m7",title:"हनुमान बीज मन्त्र",subtitle:"शक्ति, साहस र भय निवारण",tags:["मन्त्र","धर्म","शक्ति"],content:[{type:"heading",text:"बीज मन्त्र"},{type:"verse",text:"ॐ हं हनुमते नमः",translation:'"हं" हनुमानको बीज अक्षर हो। यो मन्त्रले शक्ति, साहस र निर्भयता प्रदान गर्दछ।'},{type:"heading",text:"शक्तिशाली मन्त्र"},{type:"verse",text:"ॐ हं हनुमते रुद्रात्मकाय हुं फट्",translation:"यो तान्त्रिक हनुमान मन्त्र हो। शत्रु नाश र भय निवारणको लागि जप गरिन्छ। गुरुको दीक्षा बिना यो मन्त्र जप गर्नु उचित मानिन्छैन।"},{type:"heading",text:"जप विधि"},{type:"list",items:["मंगलबार र शनिबार जप विशेष फलदायक।","रातो चन्दनको मालामा १०८ पटक जप गर्ने।","हनुमानजीको तस्बिर अगाडि बसेर जप गर्ने।","ब्रह्मचर्य (संयम) पालन गर्दा मन्त्रको शक्ति बढ्छ।","दक्षिणमुखी हनुमानको अगाडि जप गर्दा विशेष फल मिल्छ।"]},{type:"heading",text:"लाभ"},{type:"list",items:["भय, भूत-प्रेत बाधा, कालसर्प दोष निवारण","शनि ग्रहको दोष शान्त हुन्छ","मुकद्दमा, विवाद र शत्रुमाथि विजय","शारीरिक बल र मानसिक साहस बढ्छ","दुर्घटना र अकालमृत्युबाट रक्षा"]}]},{id:"m8",title:"लक्ष्मी बीज मन्त्र",subtitle:"धन, सम्पत्ति र समृद्धि",tags:["मन्त्र","धर्म","सम्पत्ति"],content:[{type:"heading",text:"बीज मन्त्र"},{type:"verse",text:`ॐ श्रीं ह्रीं श्रीं कमले कमलालये प्रसीद प्रसीद।
ॐ श्रीं ह्रीं श्रीं महालक्ष्म्यै नमः॥`,translation:'"श्रीं" लक्ष्मीको बीज अक्षर हो। कमलमा निवास गर्ने महालक्ष्मीलाई नमस्कार।'},{type:"heading",text:"सरल लक्ष्मी मन्त्र"},{type:"verse",text:"ॐ श्रीं महालक्ष्म्यै नमः",translation:"महालक्ष्मीलाई नमस्कार। यो सरल मन्त्र दैनिक जप गर्न सकिन्छ।"},{type:"heading",text:"जप विधि"},{type:"list",items:["शुक्रबार जप विशेष फलदायक।","कमलगट्टा (कमलको बीउको) मालामा जप गर्नु उत्तम।","दीपावली (लक्ष्मी पूजा) को रात विशेष जप गर्ने।","१०८ पटक जप गर्ने। ४० दिनसम्म नियमित जप गर्दा विशेष फल।","पूर्वमुख फर्केर बस्ने। लक्ष्मीको तस्बिर अगाडि दियो बाल्ने।"]},{type:"heading",text:"लाभ"},{type:"list",items:["आर्थिक समस्या र ऋणबाट मुक्ति","व्यापार र व्यवसायमा वृद्धि","गृहस्थ जीवनमा सुख-समृद्धि","दरिद्रता र अभावबाट मुक्ति","सौभाग्य र ऐश्वर्य प्राप्ति"]},{type:"paragraph",text:'<strong>विशेष:</strong> "श्री सूक्तम्" (ऋग्वेदको स्तोत्र) को पाठ गर्दा लक्ष्मी प्रसन्न हुनुहुन्छ। घरमा सफाई, सुगन्ध र दियोको उज्यालो राख्दा लक्ष्मी निवास गर्नुहुन्छ भन्ने विश्वास छ।'}]},{id:"m9",title:"नवग्रह मन्त्र",subtitle:"ग्रह दोष शान्ति",tags:["मन्त्र","ज्योतिष","शान्ति"],content:[{type:"paragraph",text:"ज्योतिष शास्त्रमा नौ ग्रह (नवग्रह) ले मानिसको जीवनमा प्रभाव पार्छन्। प्रत्येक ग्रहको आफ्नो बीज मन्त्र छ। यी मन्त्रको जपले ग्रह दोष शान्त हुन्छ र शुभ फल प्राप्त हुन्छ।"},{type:"heading",text:"नवग्रह बीज मन्त्र"},{type:"verse",text:"ॐ ह्रां ह्रीं ह्रौं सः सूर्याय नमः",translation:"सूर्य — आत्मा, पिता, राजयोग। आइतबार ७ पटक जप।"},{type:"verse",text:"ॐ श्रां श्रीं श्रौं सः चन्द्रमसे नमः",translation:"चन्द्र — मन, माता, भावना। सोमबार ११ पटक जप।"},{type:"verse",text:"ॐ क्रां क्रीं क्रौं सः भौमाय नमः",translation:"मंगल — साहस, भाइ, भूमि। मंगलबार ८ पटक जप।"},{type:"verse",text:"ॐ ब्रां ब्रीं ब्रौं सः बुधाय नमः",translation:"बुध — बुद्धि, व्यापार, वाणी। बुधबार ९ पटक जप।"},{type:"verse",text:"ॐ ग्रां ग्रीं ग्रौं सः गुरवे नमः",translation:"बृहस्पति — ज्ञान, गुरु, धर्म। बिहीबार ७ पटक जप।"},{type:"verse",text:"ॐ द्रां द्रीं द्रौं सः शुक्राय नमः",translation:"शुक्र — प्रेम, सौन्दर्य, सम्पत्ति। शुक्रबार ६ पटक जप।"},{type:"verse",text:"ॐ प्रां प्रीं प्रौं सः शनैश्चराय नमः",translation:"शनि — कर्म, कष्ट, अनुशासन। शनिबार ८ पटक जप।"},{type:"verse",text:"ॐ भ्रां भ्रीं भ्रौं सः राहवे नमः",translation:"राहु — भ्रम, माया, अचानक घटना। बुधबार/शनिबार ८ पटक जप।"},{type:"verse",text:"ॐ स्रां स्रीं स्रौं सः केतवे नमः",translation:"केतु — मोक्ष, आध्यात्मिकता, रहस्य। मंगलबार/शनिबार ७ पटक जप।"},{type:"paragraph",text:"<strong>नोट:</strong> नवग्रह मन्त्र सम्बन्धित ग्रहको दिनमा जप गर्दा विशेष फलदायक हुन्छ। ग्रह दोष जान्नको लागि कुण्डली (जन्मपत्रिका) मा ग्रहको स्थिति हेर्नुपर्छ।"}]},{id:"m10",title:"दुर्गा बीज मन्त्र",subtitle:"शक्ति, सुरक्षा र शत्रु नाश",tags:["मन्त्र","धर्म","शक्ति"],content:[{type:"heading",text:"बीज मन्त्र"},{type:"verse",text:"ॐ दुं दुर्गायै नमः",translation:'"दुं" दुर्गाको बीज अक्षर हो। शक्ति, सुरक्षा र दुष्ट शक्तिबाट मुक्तिको लागि।'},{type:"heading",text:"नवार्ण मन्त्र (९ अक्षर)"},{type:"verse",text:"ॐ ऐं ह्रीं क्लीं चामुण्डायै विच्चे",translation:"यो देवी (दुर्गा/चामुण्डा) को सबैभन्दा शक्तिशाली मन्त्र हो। यसमा तीन शक्ति — ऐं (सरस्वती), ह्रीं (लक्ष्मी), क्लीं (काली) समाहित छन्। यो मन्त्र गुरु दीक्षापछि जप गर्नु उत्तम मानिन्छ।"},{type:"heading",text:"जप विधि"},{type:"list",items:["नवरात्रिको ९ दिन जप विशेष फलदायक।","रुद्राक्षको मालामा जप गर्ने।","१०८ पटक जप गर्ने।","शुक्रबार र अष्टमी तिथिमा विशेष।","दुर्गा सप्तशती (चण्डी पाठ) सँगै जप गर्दा अत्यन्त प्रभावकारी।"]},{type:"heading",text:"लाभ"},{type:"list",items:["शत्रु, दुष्ट शक्ति र नकारात्मक ऊर्जाबाट रक्षा","साहस, आत्मविश्वास र निर्णय शक्ति बढ्छ","घरपरिवारमा शान्ति र सुरक्षा","स्त्रीहरूको सम्मान र सुरक्षा","मंगल ग्रह र राहु-केतु दोष शान्त"]}]},{id:"m11",title:"सूर्य मन्त्र",subtitle:"तेज, स्वास्थ्य र यश",tags:["मन्त्र","धर्म","स्वास्थ्य"],content:[{type:"heading",text:"सूर्य बीज मन्त्र"},{type:"verse",text:"ॐ ह्रां ह्रीं ह्रौं सः सूर्याय नमः",translation:"सूर्य देवलाई नमस्कार। यो मन्त्र ७ पटक जप गर्ने।"},{type:"heading",text:"आदित्य हृदयम् (मुख्य श्लोक)"},{type:"verse",text:`रश्मिमन्तं समुद्यन्तं देवासुरनमस्कृतम्।
पूजयस्व विवस्वन्तं भास्करं भुवनेश्वरम्॥`,translation:"किरणयुक्त, उदय हुने, देव र असुरहरूद्वारा नमस्कृत, प्रकाशमान, भुवनेश्वर सूर्यदेवको पूजा गर्नुहोस्।"},{type:"heading",text:"सूर्य नमस्कार मन्त्र (१२ नाम)"},{type:"list",items:["ॐ मित्राय नमः — सबैका मित्र","ॐ रवये नमः — प्रकाशदाता","ॐ सूर्याय नमः — सक्रिय गराउने","ॐ भानवे नमः — उज्यालो दिने","ॐ खगाय नमः — आकाशमा गमन गर्ने","ॐ पूष्णे नमः — पोषण दिने","ॐ हिरण्यगर्भाय नमः — सुनौलो गर्भ (ब्रह्माण्डको बीज)","ॐ मरीचये नमः — किरण प्रदान गर्ने","ॐ आदित्याय नमः — अदितिका पुत्र","ॐ सवित्रे नमः — उत्पादन गर्ने शक्ति","ॐ अर्काय नमः — पूजनीय","ॐ भास्कराय नमः — ज्ञानको प्रकाश दिने"]},{type:"heading",text:"जप विधि"},{type:"paragraph",text:"बिहान उदाउँदो सूर्यतिर फर्केर जल अर्घ्य दिँदै सूर्य मन्त्र जप गर्ने। आइतबार विशेष। सूर्य नमस्कार (योग) गर्दा यी १२ मन्त्र क्रमशः भन्ने। आँखाको ज्योति, हड्डी बलियो र भिटामिन डी पाउन सूर्य अर्घ्य लाभदायक छ।"}]},{id:"m12",title:"कालभैरव अष्टक",subtitle:"काशीका कोतवाल कालभैरव",tags:["मन्त्र","धर्म","शिव"],content:[{type:"paragraph",text:"कालभैरव भगवान शिवको उग्र रूप हो। उहाँलाई काशी (बनारस) को कोतवाल (रक्षक) मानिन्छ। आदि शंकराचार्यद्वारा रचित यो अष्टक कालभैरवको स्तुति हो।"},{type:"heading",text:"श्लोक १"},{type:"verse",text:`देवराजसेव्यमानपावनाङ्घ्रिपंकजं
व्यालयज्ञसूत्रमिन्दुशेखरं कृपाकरम्।
नारदादियोगिवृन्दवन्दितं दिगम्बरं
काशिकापुराधिनाथकालभैरवं भजे॥`,translation:"इन्द्रद्वारा सेवित पवित्र चरणकमल भएका, सर्पको यज्ञोपवीत र शिरमा चन्द्रमा भएका, कृपाको भण्डार, नारदादि योगीहरूद्वारा वन्दित, दिगम्बर, काशीपुराधिनाथ कालभैरवको म भजन गर्छु।"},{type:"heading",text:"श्लोक २"},{type:"verse",text:`भानुकोटिभास्वरं भवाब्धितारकं परं
नीलकण्ठमीप्सितार्थदायकं त्रिलोचनम्।
कालकालमम्बुजाक्षमक्षशूलमक्षरं
काशिकापुराधिनाथकालभैरवं भजे॥`,translation:"करोडौं सूर्यको प्रकाश भएका, संसारसागरबाट तार्ने, नीलकण्ठ, मनोकामना पूरा गर्ने, त्रिलोचन, कालको पनि काल, कमलनेत्र, अक्षमालाधारी, अविनाशी कालभैरवको म भजन गर्छु।"},{type:"heading",text:"श्लोक ३"},{type:"verse",text:`शूलटंकपाशदण्डपाणिमादिकारणं
श्यामकायमादिदेवमक्षरं निरामयम्।
भीमविक्रमं प्रभुं विचित्रताण्डवप्रियं
काशिकापुराधिनाथकालभैरवं भजे॥`,translation:"हातमा शूल, टंक, पाश र दण्ड भएका, सृष्टिको आदि कारण, श्यामवर्ण शरीर भएका, आदिदेव, अविनाशी, रोगमुक्त, भीम पराक्रमी, विचित्र ताण्डव नृत्यमा रमाउने काशीपुरका अधिनाथ कालभैरवको म भजन गर्छु।"},{type:"heading",text:"फलश्रुति"},{type:"paragraph",text:"यो अष्टक पढ्नाले काशीपुरीमा निवास गर्ने जस्तो पुण्य प्राप्त हुन्छ। सबै पापबाट मुक्ति मिल्छ र शिवलोकको प्राप्ति हुन्छ। <strong>कालाष्टमी</strong> (कृष्ण पक्ष अष्टमी) मा यो अष्टक पाठ गर्दा विशेष फलदायक हुन्छ।"}]}],n=[{id:"s1",title:"शिव ताण्डव स्तोत्रम्",subtitle:"रावण रचित शिव स्तुति",tags:["स्तोत्र","धर्म","शिव"],content:[{type:"paragraph",text:"यो स्तोत्र लंकापति रावणद्वारा भगवान शिवको स्तुतिमा रचिएको हो। यसमा शिवको शक्ति र सौन्दर्यको अद्भुत वर्णन गरिएको छ।"},{type:"heading",text:"श्लोक १"},{type:"verse",text:`जटाटवीगलज्जलप्रवाहपावितस्थले
गलेऽवलम्ब्य लम्बितां भुजङ्गतुङ्गमालिकाम्।
डमड्डमड्डमड्डमन्निनादवड्डमर्वयं
चकार चण्डताण्डवं तनोतु नः शिवः शिवम्॥१॥`,translation:"जसको जटाबाट निस्कने पवित्र जल (गंगा) को प्रवाहले पवित्र भएको घाँटीमा सर्पको माला लगाएका छन्, जसको डमरुले डम-डम आवाज गर्छ, त्यस्ता भगवान शिवले गरेको ताण्डव नृत्यले हाम्रो कल्याण गरून्।"},{type:"heading",text:"श्लोक २"},{type:"verse",text:`जटाकटाहसम्भ्रमभ्रमन्निलिम्पनिर्झरी
विलोलवीचिवल्लरीविराजमानमूर्धनि।
धगद्धगद्धगज्ज्वलल्ललाटपट्टपावके
किशोरचन्द्रशेखरे रतिः प्रतिक्षणं मम॥२॥`,translation:"जसको जटामा गंगाजीको चञ्चल लहरहरू सुशोभित छन्, जसको निधारमा अग्नि दन्किएर बलिरहेको छ, र जसको शिरमा बालचन्द्रमा विराजमान छन्, त्यस्ता भगवान शिवमा मेरो निरन्तर प्रेम रहोस्।"},{type:"heading",text:"श्लोक ३"},{type:"verse",text:`धराधरेन्द्रनन्दिनीविलासबन्धुबन्धुर
स्फुरद्दिगन्तसन्ततिप्रमोदमानमानसे।
कृपाकटाक्षधोरणीनिरुद्धदुर्धरापदि
क्वचिद्दिगम्बरे मनो विनोदमेतु वस्तुनि॥३॥`,translation:"जसको मन पर्वतराजकी पुत्री (पार्वती) को विलासमा रमेको छ, जसको कृपाले सबै दिशाहरू आनन्दित हुन्छन्, र जसले ठूला-ठूला विपत्तिहरूलाई पनि रोक्न सक्नुहुन्छ, त्यस्ता दिगम्बर (शिव) मा मेरो मन रमाओस्।"},{type:"heading",text:"श्लोक ४"},{type:"verse",text:`जटाभुजङ्गपिङ्गलस्फुरत्फणामणिप्रभा
कदम्बकुङ्कुमद्रवप्रलिप्तदिग्वधुमुखे।
मदान्धसिन्धुरस्फुरत्त्वगुत्तरीयमेदुरे
मनो विनोदमद्भुतं बिभर्तु भूतभर्तरि॥४॥`,translation:"जसको जटामा रहेका सर्पहरूको मणिको रातो प्रकाशले दिशाहरूको मुख कुमकुम लगाए जस्तै चम्किलो भएको छ, र जसले हात्तीको छालाको चादर ओढ्नुभएको छ, ती भूतनाथमा मेरो मन अद्भुत आनन्द प्राप्त गरोस्।"},{type:"heading",text:"श्लोक ५"},{type:"verse",text:`सहस्रलोचनप्रभृत्यशेषलेखशेखर
प्रसूनधूलिधोरणी विधूसराङ्घ्रिपीठभूः।
भुजङ्गराजमालया निबद्धजाटजूटकः
श्रियै चिराय जायतां चकोरबन्धुशेखरः॥५॥`,translation:"इन्द्र आदि देवताहरूले शिर निहुराउँदा उनीहरूको मुकुटको फूलको धुलोले जसको पाउ खरानी रङको भएको छ, र जसको जटा सर्पराजको मालाले बाँधिएको छ, ती चन्द्रशेखरले हामीलाई चिरस्थायी सम्पत्ति प्रदान गरून्।"},{type:"heading",text:"श्लोक ६"},{type:"verse",text:`ललाटचत्वरज्वलद्धनञ्जयस्फुलिङ्गभा
निपीतपञ्चसायकं नमन्निलिम्पनायकम्।
सुधामयूखलेखया विराजमानशेखरं
महाकपालिसम्पदे शिरोजटालमस्तु नः॥६॥`,translation:"जसले आफ्नो निधारको अग्निले कामदेवलाई भष्म गर्नुभयो, जसलाई देवताहरूले नमन गर्छन्, र जसको शिरमा चन्द्रमा सुशोभित छ, ती जटाधारी भगवान शिवले हामीलाई सिद्धि प्रदान गरून्।"},{type:"heading",text:"श्लोक ७"},{type:"verse",text:`करालभालपट्टिकाधगद्धगद्धगज्ज्वल
द्धनञ्जयाहुतीकृतप्रचण्डपञ्चसायके।
धराधरेन्द्रनन्दिनीकुचाग्रचित्रपत्रक
प्रकल्पनैकशिल्पिनि त्रिलोचने रतिर्मम॥७॥`,translation:"जसको भयानक निधारमा आगो दन्किरहेको छ, जसले कामदेवलाई हवन गर्नुभयो, र जो पर्वतराज पुत्री पार्वतीको शृङ्गार गर्नमा निपुण हुनुहुन्छ, ती त्रिलोचनमा मेरो प्रीति रहोस्।"},{type:"heading",text:"श्लोक ८"},{type:"verse",text:`नवीनमेघमण्डली निरुद्धदुर्धरस्फुरत्
कुहूनिशीथिनीतमः प्रबन्धबद्धकन्धरः।
निलिम्पनिर्झरीधरस्तनोतु कृत्तिसिन्धुरः
कलानिधानबन्धुरः श्रियं जगद्धुरन्धरः॥८॥`,translation:"जसको घाँटी नयाँ बादल वा औंसीको रात जस्तै कालो छ, जसले गंगा र गजासुरको छाला धारण गर्नुभएको छ, ती चन्द्रमा धारण गर्ने जगत्का भार बोक्ने शिवले हामीलाई सम्पत्ति दिनुहोस्।"},{type:"heading",text:"श्लोक ९"},{type:"verse",text:`प्रफुल्लनीलपङ्कजप्रपञ्चकालिमप्रभा
वलम्बिकण्ठकन्दलीरुचिप्रबद्धकन्धरम्।
स्मरच्छिदं पुरच्छिदं भवच्छिदं मखच्छिदं
गजच्छिदान्धकच्छिदं तमन्त कच्छिदं भजे॥९॥`,translation:"जसको घाँटी नीलो कमल जस्तै कालो र सुन्दर छ; जसले कामदेव, त्रिपुरासुर, संसारको बन्धन, र अन्धकासुरलाई नाश गर्नुभयो; म उहाँ (मृत्युको पनि नाश गर्ने) को भजन गर्छु।"},{type:"heading",text:"श्लोक १०"},{type:"verse",text:`अखर्वसर्वमङ्गलाकलाकदम्बमञ्जरी
रसप्रवाहमाधुरी विजृम्भणामधुव्रतम्।
स्मरान्तकं पुरान्तकं भवान्तकं मखान्तकं
गजान्तकान्धकान्तकं तमन्तकान्तकं भजे॥१०॥`,translation:"जो पार्वतीको कला रूपी रसको आस्वादन गर्ने भ्रमरा हुनुहुन्छ, र जसले काल (मृत्यु), कामदेव र त्रिपुरासुरको नाश गर्नुभयो, म ती शिवको भजन गर्छु।"},{type:"heading",text:"श्लोक ११"},{type:"verse",text:`जयत्वदभ्रविभ्रमभ्रमद्भुजङ्गमश्वस
द्विनिर्गमत्क्रमस्फुरत्करालभालहव्यवाट्।
धिमिद्धिमिद्धिमिध्वनन्मृदङ्गतुङ्गमङ्गल
ध्वनिक्रमप्रवर्तित प्रचण्डताण्डवः शिवः॥११॥`,translation:"जसको निधारको अग्नि सर्पको स्वासले अझ तेजिलो भएको छ, र जो मृदङ्गको धिमि-धिमि मंगल आवाजसँगै प्रचण्ड ताण्डव नाचिरहनुभएको छ, ती शिवको जय होस्।"},{type:"heading",text:"श्लोक १२"},{type:"verse",text:`दृषद्विचित्रतल्पयोर्भुजङ्गमौक्तिकस्रजो
र्गरिष्ठरत्नलोष्ठयोः सुहृद्विपक्षपक्षयोः।
तृणारविन्दचक्षुषोः प्रजामहीमहेन्द्रयोः
समप्रवृत्तिकः कदा सदाशिवं भजाम्यहम्॥१२॥`,translation:"पत्थर र सुन्दर ओछ्यान, सर्प र मोतीको माला, रत्न र माटो, मित्र र शत्रु, तथा प्रजा र राजालाई समान देख्ने भाव राखेर म कहिले सदाशिवको भजन गरूँला?"},{type:"heading",text:"श्लोक १३"},{type:"verse",text:`कदा निलिम्पनिर्झरीनिकुञ्जकोटरे वसन्
विमुक्तदुर्मतिः सदा शिरःस्थमञ्जलिं वहन्।
विमुक्तलोललोचनो ललामभाललग्नकः
शिवेति मन्त्रमुच्चरन् कदा सुखी भवाम्यहम्॥१३॥`,translation:'गङ्गाको तटमा बस्दै, दुष्ट विचार त्यागेर, शिरमा हात जोड्दै र निधारमा भष्म लगाएर "शिव" मन्त्र उच्चारण गर्दै म कहिले सुखी हूँला?'},{type:"heading",text:"श्लोक १४"},{type:"verse",text:`निलिम्पनाथनागरीकदम्बमौलिमल्लिका-
निगुम्फनिर्भक्षरन्मधूष्णिकामनोहरः।
तनोतु नो मनोमुदं विनोदिनीमहर्निशं
पठिष्यतः परं पदं तदङ्गजत्विषां चयः॥१४॥`,translation:"देवताहरूकी नगरका स्त्रीहरू (अप्सराहरू) को शिरमा रहेका मल्लिका र कदम्बका फूलहरूको मालाबाट झर्ने सुगन्धित मकरन्दले मनमोहक भएको, र जसले निरन्तर आनन्द दिन्छ, त्यस्तो भगवान शिवको अंगको कान्तिले हामीलाई परम आनन्द र उच्च स्थान (मोक्ष) प्रदान गरोस्।"},{type:"heading",text:"श्लोक १५"},{type:"verse",text:`इमं हि नित्यमेवमुक्तमुत्तमोत्तमं स्तवं
पठन्स्मरन्ब्रूवन्ररो विशुद्धिमेतिसन्ततम्।
हरे गुरौ सुभक्तिमाशु याति नान्यथा गतिं
विमोहनं हि देहिनां सुशङ्करस्य चिन्तनम्॥१५॥`,translation:"यो उत्तम स्तोत्रको नित्य पाठ, स्मरण वा वर्णन गर्नाले मानिस पवित्र हुन्छ र शिवजीमा गहिरो भक्ति प्राप्त गर्दछ।"},{type:"heading",text:"श्लोक १६"},{type:"verse",text:`पूजावसानसमये दशवक्त्रगीतं
यः शम्भूपूजनपरं पठति प्रदोषे।
तस्य स्थिरां रथगजेन्द्रतुरङ्गयुक्तां
लक्ष्मीं सदैव सुमुखिं प्रददाति शम्भुः॥१६॥`,translation:"पूजाको अन्त्यमा वा प्रदोष कालमा जसले रावणद्वारा रचित यो स्तुति पाठ गर्छ, भगवान शम्भुले उसलाई रथ, हात्ती र घोडासहितको स्थिर लक्ष्मी (सम्पत्ति) प्रदान गर्नुहुन्छ।"},{type:"paragraph",text:"यो स्तोत्र विशेष गरी महाशिवरात्रिको दिन वा प्रत्येक सोमबारमा पाठ गरिन्छ। शिवजीको कृपा प्राप्त गर्न यो अत्यन्त प्रभावकारी मानिन्छ।"}]},{id:"s2",title:"अच्युताष्टकम्",subtitle:"भगवान विष्णुको स्तुति",tags:["स्तोत्र","धर्म","विष्णु"],content:[{type:"heading",text:"श्लोक १"},{type:"verse",text:`अच्युतं केशवम् रामनारायणम्
कृष्णदामोदरम् वासुदेवम् हरिम्।
श्रीधरम् माधवम् गोपिकावल्लभम्
जानकीनायकम् रामचन्द्रम् भजे॥१॥`,translation:"म अच्युत, केशव, राम, नारायण, कृष्ण, दामोदर, वासुदेव, हरि, श्रीधर, माधव, गोपिकावल्लभ, र जानकीनायक रामचन्द्रको भजन गर्दछु।"},{type:"heading",text:"श्लोक २"},{type:"verse",text:`अच्युतं केशवं सत्यभामाधवं
माधवं श्रीधरं राधिकाराधितम्।
इन्दिरामन्दिरं चेतसा सुन्दरं
देवकीनन्दनं नन्दजं सन्दधे॥२॥`,translation:"म अच्युत, केशव, सत्यभामाका पति, लक्ष्मीका पति, राधाद्वारा पूजित, इन्दिरा (लक्ष्मी) को मन्दिर, मनलाई मोहित पार्ने सुन्दर, देवकीका पुत्र र नन्दका छोरा (कृष्ण) को ध्यान गर्दछु।"},{type:"heading",text:"श्लोक ३"},{type:"verse",text:`विष्णवे जिष्णवे शङ्खिने चक्रिणे
रुक्मिणीरागिणे जानकीजानये।
बल्लवीवल्लभायार्चितायात्मने
कंसविध्वंसिने वंशिने ते नमः॥३॥`,translation:"विष्णु, जिष्णु (विजयी), शङ्ख र चक्र धारण गर्ने, रुक्मिणीका प्रेमी, जानकी (सीता) का पति, गोपिनीहरूका प्रिय, पूजित परमात्मा, र कंसको विनाश गर्ने बाँसुरी वादक हजुरलाई नमस्कार छ।"},{type:"heading",text:"श्लोक ४"},{type:"verse",text:`कृष्ण गोविन्द हे राम नारायण
श्रीपते वासुदेवाजित श्रीनिधे।
अच्युतानन्त हे माधवाधोक्षज
द्वारकानायक द्रौपदीरक्षक॥४॥`,translation:"हे कृष्ण! हे गोविन्द! हे राम! हे नारायण! हे श्रीपति (लक्ष्मीपति)! हे वासुदेव! हे अजित! हे श्रीनिधि! हे अच्युत! हे अनन्त! हे माधव! हे अधोक्षज! हे द्वारकाका नायक! हे द्रौपदीका रक्षक! (मेरो रक्षा गर्नुहोस्)।"},{type:"heading",text:"श्लोक ५"},{type:"verse",text:`राक्षसक्षोभितः सीतया शोभितो
दण्डकारण्यभूपुण्यताकारणः।
लक्ष्मणेनान्वितो वानरैः सेवितो
अगस्त्यसम्पूजितो राघव पातु माम्॥५॥`,translation:"राक्षसहरूलाई क्षुब्ध पार्ने, सीताजीद्वारा सुशोभित, दण्डकारण्य भूमि पवित्र बनाउने कारण, लक्ष्मणद्वारा अनुगमन गरिएका, बाँदरहरूद्वारा सेवित, र अगस्त्य ऋषिद्वारा पूजित हे राघव (राम)! मेरो रक्षा गर्नुहोस्।"},{type:"heading",text:"श्लोक ६"},{type:"verse",text:`धेनुकारिष्टहानिष्टकृद्वेषिणाम्
केशिहा कंसहृद्वंशिकावादकः।
पूतनाकोपकः सूरजाखेलनो
बालगोपालकः पातु मां सर्वदा॥६॥`,translation:"धेनुकासुर र अरिष्टासुरको नास गर्ने, शत्रुहरूको अनिष्ट गर्ने, केशी र कंसको हत्या गर्ने, बाँसुरी बजाउने, पूतनाप्रति क्रोधित हुने, यमुना (सूरजा) मा खेल्ने बालगोपालले सधैं मेरो रक्षा गरून्।"},{type:"heading",text:"श्लोक ७"},{type:"verse",text:`विद्युदुद्योतवत्प्रस्फुरद्वाससं
प्रावृडम्भोदवत्प्रोल्लसद्विग्रहम्।
वन्यया मालया शोभितोरःस्थलं
लोहिताङ्घ्रिद्वयं वारिजाक्षं भजे॥७॥`,translation:"बिजुली जस्तै चम्किलो पहेँलो बस्त्र लगाउने, वर्षाको बादल जस्तै सुन्दर शरीर भएका, वनमालाले सुशोभित छाती भएका, रातो र सुन्दर पाउ भएका, र कमल जस्तै आँखा भएका भगवानको म भजन गर्छु।"},{type:"heading",text:"श्लोक ८"},{type:"verse",text:`कुञ्चितैः कुन्तलैर्भ्राजमानाननं
रत्नमौलिं लसत्कुण्डलं गण्डयोः।
हारकेयूरकं कङ्कणप्रोज्ज्वलं
किङ्किणीमञ्जुलं श्यामलं तं भजे॥८॥`,translation:"घुम्रेको कपालले सुशोभित अनुहार भएका, रत्नजडित मुकुट र कानमा चम्किलो कुण्डल लगाएका, हार, बाजूबन्द र कङ्कणले सजिएका, र पाउजुको आवाजले मनमोहक, त्यस्ता श्यामसुन्दरको म भजन गर्छु।"},{type:"heading",text:"श्लोक ९ (फलश्रुति)"},{type:"verse",text:`अच्युतस्याष्टकं यः पठेदिष्टदं
प्रेमतः प्रत्यहं पूरुषः सस्पृहम्।
वृत्ततः सुन्दरं कर्तृविश्वम्भरं
तस्य वश्यो हरिर्जायते सत्वरम्॥९॥`,translation:"जो मानिस प्रेमपूर्वक यो फलदायी अच्युताष्टकको नित्य पाठ गर्छ, सम्पूर्ण विश्वका पालनकर्ता र अत्यन्त सुन्दर भगवान हरि छिट्टै उसको वशमा हुनुहुन्छ (प्रसन्न हुनुहुन्छ)।"},{type:"paragraph",text:"यो स्तोत्र विशेष गरी विष्णु पूजा वा प्रत्येक बिहीबारमा पाठ गरिन्छ। विष्णुजीको कृपा प्राप्त गर्न यो अत्यन्त प्रभावकारी मानिन्छ।"}]},{id:"s3",title:"महिषासुर मर्दिनी स्तोत्रम्",subtitle:"देवी दुर्गाको शक्ति स्तुति",tags:["स्तोत्र","धर्म","दुर्गा"],content:[{type:"paragraph",text:"यो स्तोत्र आदि शंकराचार्यद्वारा रचित मानिन्छ। यसमा देवी दुर्गाको शक्ति र महिषासुर वधको वर्णन छ।"},{type:"heading",text:"श्लोक १"},{type:"verse",text:`अयि गिरिनन्दिनि नन्दितमेदिनि विश्वविनोदिनि नन्दनुते
गिरिवरविन्ध्यशिरोऽधिनिवासिनि विष्णुविलासिनि जिष्णुनुते।
भगवति हे शितिकण्ठकुटुम्बिनि भूरिकुटम्बिनि भूरिकृते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥१॥`,translation:"हे हिमालयकी छोरी, पृथ्वीलाई आनन्दित तुल्याउने, विश्वलाई मोहित पार्ने, नन्दीद्वारा पूजित, विन्ध्याचलको शिखरमा निवास गर्ने, भगवान विष्णुलाई प्रसन्न पार्ने, इन्द्रद्वारा पूजित, भगवान शिवकी पत्नी, र सम्पूर्ण जगतकी माता! हे महिषासुरको वध गर्ने देवी! तिम्रो जय होस्, जय होस्!"},{type:"heading",text:"श्लोक २"},{type:"verse",text:`सुरवरवर्षिणि दुर्धरधर्षिणि दुर्मुखमर्षिणि हर्षरते
त्रिभुवनपोषिणि शंकरतोषिणि किल्बिषमोषिणि घोषरते।
दनुजनिरोषिणि दितिसुतरोषिणि दुर्मदशोषिणि सिन्धुसुते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥२॥`,translation:"देवताहरूलाई वरदान दिने, दुष्टहरूलाई दमन गर्ने, दुर्मुख असुरलाई मार्ने, सधैं हर्षित रहने, तीनै लोकको पालनपोषण गर्ने, शिवलाई सन्तुष्ट पार्ने, पाप नाश गर्ने, र युद्धको आवाजमा रम्ने हे देवी! तिम्रो जय होस्!"},{type:"heading",text:"श्लोक ३"},{type:"verse",text:`अयि जगदम्ब मदम्ब कदम्बवनप्रियवासिनि हासरते
शिखरिशिरोमणितुङ्घि हिमालयशृङ्घिनिजालयमध्यगते।
मधुमधुरे मधुकैटभगञ्जिनि कैटभभञ्जिनि रासरते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥३॥`,translation:"हे जगत् जननी! जो कदम्बको वनमा बस्न रुचाउनुहुन्छ, जो हाँसखेलमा मग्न हुनुहुन्छ, जो हिमालयको उच्च शिखरमा बस्नुहुन्छ, र जसले मह जस्तै गुलियो तर मधु र कैटभ जस्ता राक्षसको नाश गर्नुभयो, हे महिषासुर मर्दिनी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक ४"},{type:"verse",text:`अयि शतखण्ड-विखण्डितरुण्ड-वितुण्डितशुण्ड-गजाधिपते
रिपुगज-गण्डविदारण-चण्डपराक्रम-शुण्डमृगाधिपते।
निजभुजदण्ड-निपातितखण्ड-विपातितमुण्ड-भटाधिपते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥४॥`,translation:"जसले शत्रुको हात्तीहरूको सेनालाई सयौं टुक्रामा काटिदिनुभयो, जसको सिंहले शत्रुहरूको हात्तीको टाउको फोड्ने पराक्रम राख्छ, र जसले आफ्नो भुजाको बलले शत्रु योद्धाहरूको टाउको काटिदिनुभयो, हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक ५"},{type:"verse",text:`अयि रणदुर्मद-शत्रुवधोदित-दुर्धरनिर्जर-शक्तिभृते
चतुरविचार-धुरीणमहाशिव-दूतकृत-प्रमथाधिपते।
दुरितदुरीह-दुराशयदुर्मति-दानवदूत-कृतान्तमते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥५॥`,translation:"जसले युद्धमा उन्मत्त शत्रुहरूको नाश गर्न देवताहरूको शक्ति धारण गर्नुभयो, जसले भगवान शिवलाई दूत बनाएर पठाउनुभयो, र जसले दुष्ट विचार भएका दानवहरूका दूतको घमण्ड तोड्नुभयो, हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक ६"},{type:"verse",text:`अयि शरणागत-वैरिवधुवर-वीरवराभय-दायकरे
त्रिभुवनमस्तक-शूलविरोधिशिरोऽधिकृतामल-शूलकरे।
दुमिदुमितामर-दुन्दुभिनाद-महोमुखरीकृत-तिग्मकरे
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥६॥`,translation:"जसले शरणमा आएका शत्रुहरूकी पत्नीहरूलाई अभयदान (सुरक्षा) दिनुहुन्छ, जसले त्रिशूलले शत्रुहरूको शिर छेदन गर्नुहुन्छ, र जसको आगमनमा देवताहरूको दुन्दुभी (बाजा) को आवाज गुञ्जिन्छ, हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक ७"},{type:"verse",text:`अयि निजहुङ्कृति-मात्रनिराकृत-धूम्रविलोचन-धूम्रशते
समरविशोषित-शोणितबीज-समुद्भवशोणित-बीजलते।
शिवशिव-शुम्भनिशुम्भ-महाहवतर्पित-भूतपिशाचरते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥७॥`,translation:'जसले आफ्नो "हुंकार" मात्रले धूम्रलोचन राक्षसलाई भष्म गर्नुभयो, जसले रक्तबीजको रगतबाट उत्पन्न हुने राक्षसहरूलाई नाश गर्नुभयो, र जसले शुम्भ-निशुम्भको वध गरेर भूत-प्रेतहरूलाई तृप्त पार्नुभयो, हे देवी! तिम्रो जय होस्।'},{type:"heading",text:"श्लोक ८"},{type:"verse",text:`धनु रनुषङ्ग रणक्षणसङ्ग परिस्फुरदङ्ग नटत्कटके
कनकपिशङ्ग पृषत्कनिषङ्ग रसद्भटशृङ्ग हताबटुके।
कृतचतुरङ्ग बलक्षितिरङ्ग घटद्बहरङ्ग रटद्बटुके
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥८॥`,translation:"युद्धको मैदानमा जसको हातमा धनुष र बाणहरू शोभायमान छन्, जसको सुनौलो रङको शरीरमा शत्रुहरूलाई नाश गर्ने शक्ति छ, र जो चतुरङ्गिनी सेनालाई नाश गर्दै युद्धभूमिमा रम्नुहुन्छ, हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक ९"},{type:"verse",text:`जय जय जप्यजयेजयशब्द-परस्तुतितत्पर-विश्वनुते
झणझणझिञ्झिमि-झिङ्कृतनूपुर-सिञ्जितमोहित-भूतपते।
नटितनटार्ध-नटीनटीनायक-नाटितनाट्य-सुगानरते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥९॥`,translation:'सम्पूर्ण विश्वले जसको "जय होस्" भनी स्तुति गर्छ, जसको पाउजुको "झण-झण" आवाजले भगवान शिव (भूतपति) लाई मोहित पार्छ, र जो शिवको अर्धांगिनी भई नृत्य र गानमा लीन हुनुहुन्छ, हे देवी! तिम्रो जय होस्।'},{type:"heading",text:"श्लोक १० (सरलीकृत)"},{type:"verse",text:`अयि सुमनः सुमनः सुमनः सुमनः-सुमनोहरकान्तियुते
श्रितरजनी रजनी रजनी रजनी-रजनीकरवक्त्रवृते।
सुनयनविभ्रम-रभ्रम-रभ्रम-रभ्रम-रभ्रमराधिपते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥१०॥`,translation:"जसको मन पवित्र छ, जो धेरै सुन्दर फूलहरू जस्तै कोमल र मनमोहक कान्तिले युक्त हुनुहुन्छ, जसको मुहार चन्द्रमा जस्तै चम्किलो छ, र जसको सुन्दर आँखामा भ्रमराहरू जस्तै आकर्षण छ, हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक ११"},{type:"verse",text:`सहितमहाहव-मल्लमतल्लिक-मल्लितरल्लक-मल्लरते
विरचितवल्लिक-पल्लिकमल्लिक-झिल्लिकभिल्लिक-वर्गवृते।
सितकृतफुल्लि-समुल्लिसितारुण-तल्लजपल्लव-सल्ललिते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥११॥`,translation:"जो महायुद्धमा मल्ल युद्ध गर्न सिपालु हुनुहुन्छ, जो भील (वनवासी) स्त्रीहरूको समूहद्वारा घेरिएर रहनुहुन्छ, र जसमा रातो रङ्गको कोमल पालुवा जस्तै सौन्दर्य र लालित्य छ, हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक १२"},{type:"verse",text:`अविरलगण्ड-गलन्मदमेदुर-मत्तमतङ्ग-छराजपते
त्रिभुवनभूषण-भूतकलानिधि-रूपपयोनिधि-राजसुते।
अयि सुदतीजन-लालसमानस-मोहनमन्मथ-राजसुते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥१२॥`,translation:"मत्त हात्तीहरूको बीचमा जसको सवारी हुन्छ, जो तीनै लोकको आभूषण र चन्द्रमा जस्तै सुन्दर हुनुहुन्छ, र जो कामदेव (मन्मथ) को मनलाई पनि मोहित पार्ने सुन्दरी हुनुहुन्छ, हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक १३"},{type:"verse",text:`कमलदलामल-कोमलकान्ति-कलाकलितामल-भाललते
सकलविलास-कलानिलयक्रम-केलिचलत्कल-हंसकुले।
अलिकुलसङ्कुल-कुवलयमण्डल-मौलिमिलद्बकुलालिकुले
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥१३॥`,translation:"जसको निधार कमलको पात जस्तै कोमल र स्वच्छ छ, जो हाँसहरूको चाल जस्तै सुन्दर हिड्नुहुन्छ, र जसको कपालमा भ्रमराहरूले घेरिएको बकुलको फूलको माला छ, हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक १४"},{type:"verse",text:`करमुरलीरव-वीजितकूजित-लज्जितकोकिल-मञ्जुमते
मिलितपुलिन्द-मनोहरगुञ्जित-रञ्जितशैल-निकुञ्जगते।
निजगणभूत-महाशबरीगण-सद्गुणसम्भृत-केलितले
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥१४॥`,translation:"जसको मुरलीको आवाज सुनेर कोइली पनि लजाउँछ, जो पर्वतका निकुञ्जहरूमा घुम्दै आनन्द लिनुहुन्छ, र जो आफ्ना शबरी गणहरूसँग मिलेर लीला गर्नुहुन्छ, हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक १५"},{type:"verse",text:`कटितटपीत-दुकूलविचित्र-मयूखतिरस्कृत-चन्द्ररुचे
प्रणतसुरासुर-मौलिमणिस्फुर-दंशुलसन्नख-चन्द्ररुचे।
जितकनकाचल-मौलिमदोर्जित-निर्भरकुञ्जर-कुम्भकुचे
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥१५॥`,translation:"जसले कम्मरमा लगाएको पहेँलो रेशमी वस्त्रको कान्तिले चन्द्रमालाई पनि जितेको छ, जसको पाउका नङहरू देवता र असुरहरूको मुकुटको मणिको प्रकाशले चम्किरहेका छन्, हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक १६ (सरलीकृत)"},{type:"verse",text:`विजित-सहस्रकरैक-सहस्रकरैक-सहस्रकरैक-नुते
कृत-सुर-तारक-सङ्गर-तारक-सङ्गर-तारकसूनु-नुते।
सुरथ-समाधि-समान-समाधि-समाधि-समाधि-सुजात-रते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥१६॥`,translation:"हजारौं हात भएका सूर्यको तेजलाई जित्ने, तारकासुरको वध गर्ने कार्तिकेय (तारकसूनु) द्वारा पूजित, र सुरथ राजा तथा समाधि वैश्यद्वारा गरएको तपस्याबाट प्रसन्न हुने हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक १७"},{type:"verse",text:`पदकमलं करुणानिलये वरिवस्यति योऽनुदिनं सुशिवे
अयि कमले कमलानिलये कमलानिलयः स कथं न भवेत्।
तव पदमेव परम्पदमेवमनुशीलयतो मम किं न शिवे
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥१७॥`,translation:"हे दयाकी खानी! जो मानिसले तिम्रो चरण कमलको नित्य सेवा गर्छ, ऊ किन धनी (कमलानिलय) नहोला? हे शिवे! तिम्रो चरणको ध्यान गर्नाले मलाई पनि किन परम पद (मोक्ष) प्राप्त नहोला?"},{type:"heading",text:"श्लोक १८"},{type:"verse",text:`कनकलसत्कल-सिन्धुजलैरनु-सिञ्चिनुते गुणरङ्गभुवम्
भजति स किं न शचीकुचकुम्भ-तटीपरिरम्भ-सुखानुभवम्।
तव चरणं शरणं करवाणि नतामरवाणि-निवासिशिवम्
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥१८॥`,translation:"जसले सुनको घडामा पवित्र जल लिएर तिम्रो अभिषेक गर्छ, उसले इन्द्रको जस्तो सुख किन नपाउला? म तिम्रै चरणमा शरण पर्दछु, जहाँ सरस्वती र शिव निवास गर्नुहुन्छ। हे देवी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक १९"},{type:"verse",text:`तव विमलेन्दुकुलं वदनेन्दुमलं सकलं ननु कूलयते
किमु पुरुहूत-पुरीन्दुमुखी-सुमुखीभिरसौ विमुखीक्रियते।
मम तु मतं शिवनामधने भवती कृपया किमुत क्रियते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥१९॥`,translation:"तिम्रो चन्द्रमा जस्तो निर्मल मुहारको ध्यान गर्ने मानिसलाई स्वर्गका अप्सराहरूले पनि रिझाउन सक्दैनन् (अर्थात् ऊ सांसारिक मोहबाट माथि उठ्छ)। हे शिवप्रिया! ममाथि कृपा गर्नुहोस्।"},{type:"heading",text:"श्लोक २०"},{type:"verse",text:`अयि मयि दीनदयालुतया कृपयैव त्वया भवितव्यमुमे
अयि जगतो जननी कृपयासि यथासि तथानुमितासिरते।
यदुचितमत्र भवत्युररीकुरुतादुरुतापमपाकुरुते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥२०॥`,translation:"हे उमा! म दीन-दुःखी माथि दयालु भई कृपा गर्नुहोस्। तिमी नै जगतकी आमा हौ। मेरो दुःख र तापलाई हटाई मलाई जुन उचित हुन्छ, त्यही गर्नुहोस्। हे महिषासुर मर्दिनी! तिम्रो जय होस्।"},{type:"heading",text:"श्लोक २१"},{type:"verse",text:`स्तोत्रं ममैतत्क्रियते जनन्यै
क्षम्यन्त्विमे भूलमकारयित्री।
भक्त्यैकभावेन निवेदयामि
क्षमस्व देव्यै जगदम्बिकेति॥२१॥`,translation:"मैले मेरो आमा (देवी) को लागि यो स्तुति गाएको हुँ। यसमा भएका गल्तीहरू क्षमा गर्नुहोस्। म भक्तिभावले यो समर्पण गर्दछु, हे जगदम्बिका! मलाई माफ गर्नुहोस्।"},{type:"paragraph",text:"यो स्तोत्र विशेष गरी दुर्गा पूजा वा प्रत्येक नवरात्रिको समयमा पाठ गरिन्छ। देवी दुर्गाको कृपा प्राप्त गर्न यो अत्यन्त प्रभावकारी मानिन्छ।"}]},{id:"s4",title:"मधराष्टकम्",subtitle:"भगवान कृष्णको मधुरताको वर्णन",tags:["स्तोत्र","धर्म","कृष्ण"],content:[{type:"paragraph",text:"वल्लभाचार्यद्वारा रचित यो अष्टकममा भगवान श्रीकृष्णको बाललीला, रूप, र गुणहरूको मधुरताको वर्णन गरिएको छ।"},{type:"heading",text:"श्लोक १"},{type:"verse",text:`अधरं मधुरं वदनं मधुरं नयनं मधुरं हसितं मधुरम्।
हृदयं मधुरं गमनं मधुरं मधुराधिपतेरखिलं मधुरम्॥१॥`,translation:"भगवान कृष्णका ओठ मधुर छन्, अनुहार मधुर छ, आँखाहरू मधुर छन्, हाँसो मधुर छ। उहाँको हृदय मधुर छ, हिँडाइ मधुर छ। मधुरताका स्वामी (श्रीकृष्ण) को सबै थोक मधुर छ।"},{type:"heading",text:"श्लोक २"},{type:"verse",text:`वचनं मधुरं चरितं मधुरं वसनं मधुरं वलितं मधुरम्।
चलितं मधुरं भ्रमितं मधुरं मधुराधिपतेरखिलं मधुरम्॥२॥`,translation:"उहाँका वचन मधुर छन्, चरित्र मधुर छ, वस्त्र मधुर छन्, अंगभंगी मधुर छ। उहाँको हिँडाइ र घुमाइ पनि मधुर छ। मधुरताका स्वामीको सबै थोक मधुर छ। "},{type:"heading",text:"श्लोक ३"},{type:"verse",text:`वेणुर्मधुरो रेणुर्मधुरः पाणिर्मधुरः पादौ मधुरौ।
नृत्यं मधुरं सख्यं मधुरं मधुराधिपतेरखिलं मधुरम्॥३॥`,translation:"उहाँको बाँसुरी मधुर छ, चरणको धुलो (रेणु) मधुर छ, हातहरू मधुर छन्, पाउहरू मधुर छन्। उहाँको नृत्य मधुर छ, मित्रता मधुर छ। मधुरताका स्वामीको सबै थोक मधुर छ।"},{type:"heading",text:"श्लोक ४"},{type:"verse",text:`गीतं मधुरं पीतं मधुरं भुक्तं मधुरं सुप्तं मधुरम्।
रूपं मधुरं तिलकं मधुरं मधुराधिपतेरखिलं मधुरम्॥४॥`,translation:"उहाँको गीत मधुर छ, पिउनु (पानी आदि) मधुर छ, भोजन मधुर छ, शयन (सुताइ) मधुर छ। उहाँको रूप मधुर छ, टीका (तिलक) मधुर छ। मधुरताका स्वामीको सबै थोक मधुर छ।"},{type:"heading",text:"श्लोक ५"},{type:"verse",text:`करणं मधुरं तरणं मधुरं हरणं मधुरं रमणं मधुरम्।
वमितं मधुरं शमितं मधुरं मधुराधिपतेरखिलं मधुरम्॥५॥`,translation:"उहाँको कार्य मधुर छ, तार्नु (उद्धार गर्नु) मधुर छ, हरण गर्नु (दुःख वा मन) मधुर छ, रम्नु (क्रीडा) मधुर छ। उहाँको उद्गार (बोल्नु) मधुर छ, शान्ति मधुर छ। मधुरताका स्वामीको सबै थोक मधुर छ।"},{type:"heading",text:"श्लोक ६"},{type:"verse",text:`गुञ्जा मधुरा माला मधुरा यमुना मधुरा वीची मधुरा।
सलिलं मधुरं कमलं मधुरं मधुराधिपतेरखिलं मधुरम्॥६॥`,translation:"उहाँको गुञ्जाको माला मधुर छ, गलामा लगाउने माला मधुर छ, यमुना नदी मधुर छिन्, (यमुनाको) छालहरू मधुर छन्। त्यहाँको पानी मधुर छ, कमलको फूल मधुर छ। मधुरताका स्वामीको सबै थोक मधुर छ।"},{type:"heading",text:"श्लोक ७"},{type:"verse",text:`गोपी मधुरा लीला मधुरा युक्तं मधुरं मुक्तं मधुरम्।
दृष्टं मधुरं शिष्टं मधुरं मधुराधिपतेरखिलं मधुरम्॥७॥`,translation:"गोपिनीहरू मधुर छन्, उहाँको लीला मधुर छ, मिलन मधुर छ, विछोड (मुक्ति) मधुर छ। उहाँको हेराइ (दृष्टि) मधुर छ, शिष्टाचार मधुर छ। मधुरताका स्वामीको सबै थोक मधुर छ।"},{type:"heading",text:"श्लोक ८"},{type:"verse",text:`गोपा मधुरा गावो मधुरा यष्टिर्मधुरा सृष्टिर्मधुरा।
दलितं मधुरं फलितं मधुरं मधुराधिपतेरखिलं मधुरम्॥८॥`,translation:"ग्वालाहरू (गोठाला) मधुर छन्, गाईहरू मधुर छन्, उहाँको लट्ठी (यष्टि) मधुर छ, सृष्टि मधुर छ। उहाँले दुष्टको दमन गर्नु (दल्नु) मधुर छ, वरदान दिनु (फल्नु) मधुर छ। मधुरताका स्वामीको सबै थोक मधुर छ।"},{type:"paragraph",text:"यो अष्टकम विशेष गरी कृष्ण पूजा वा प्रत्येक शनिवारमा पाठ गरिन्छ। भगवान कृष्णको कृपा प्राप्त गर्न यो अत्यन्त प्रभावकारी मानिन्छ।"}]},{id:"s5",title:"श्री हनुमान चालीसा",subtitle:"तुलसीदास रचित",tags:["स्तोत्र","धर्म","हनुमान"],content:[{type:"heading",text:"दोहा"},{type:"verse",text:`श्रीगुरु चरन सरोज रज, निज मनु मुकुरु सुधारि।
बरनउँ रघुबर बिमल जसु, जो दायकु फल चारि॥`,translation:"श्री गुरुदेवको चरणकमलको धुलोले आफ्नो मनरूपी ऐनालाई सफा गरेर, म श्री रघुनाथजीको निर्मल यशको वर्णन गर्दछु, जसले धर्म, अर्थ, काम र मोक्ष रूपी चार फल दिन्छ।"},{type:"verse",text:`बुद्धिहीन तनु जानिके, सुमिरौं पवनकुमार।
बल बुधि बिद्या देहु मोहिं, हरहु कलेस बिकार॥`,translation:"आफूलाई बुद्धिहीन जानेर म पवनपुत्र हनुमानको स्मरण गर्दछु। मलाई बल, बुद्धि र विद्या दिनुहोस्, र मेरा सबै कष्ट तथा दोषहरू हरण गर्नुहोस्।"},{type:"heading",text:"चौपाई (१-१०)"},{type:"paragraph",text:`जय हनुमान ज्ञान गुन सागर। जय कपीस तिहुं लोक उजागर॥१॥
रामदूत अतुलित बल धामा। अंजनिपुत्र पवनसुत नामा॥२॥
महाबीर बिक्रम बजरंगी। कुमति निवार सुमति के संगी॥३॥
कंचन बरन बिराज सुबेसा। कानन कुंडल कुंचित केसा॥४॥
हाथ बज्र औ ध्वजा बिराजै। काँधे मूँज जनेऊ साजै॥५॥
संकर सुवन केसरीनंदन। तेज प्रताप महा जग बंदन॥६॥
बिद्यावान गुनी अति चातुर। राम काज करिबे को आतुर॥७॥
प्रभु चरित्र सुनिबे को रसिया। राम लखन सीता मन बसिया॥८॥
सूक्ष्म रूप धरि सियहिं दिखावा। बिकट रूप धरि लंक जरावा॥९॥
भीम रूप धरि असुर सँहारे। रामचंद्र के काज सँवारे॥१०॥`},{type:"heading",text:"चौपाई (११-२०)"},{type:"paragraph",text:`लाय सजीवन लखन जियाये। श्रीरघुबीर हरषि उर लाये॥११॥
रघुपति कीन्ही बहुत बड़ाई। तुम मम प्रिय भरतहि सम भाई॥१२॥
सहस बदन तुम्हरो जस गावैं। अस कहि श्रीपति कंठ लगावैं॥१३॥
सनकादिक ब्रह्मादि मुनीसा। नारद सारद सहित अहीसा॥१४॥
जम कुबेर दिगपाल जहाँ ते। कबि कोबिद कहि सके कहाँ ते॥१५॥
तुम उपकार सुग्रीवहिं कीन्हा। राम मिलाय राज पद दीन्हा॥१६॥
तुम्हरो मंत्र बिभीषन माना। लंकेस्वर भए सब जग जाना॥१७॥
जुग सहस्र जोजन पर भानू। लील्यो ताहि मधुर फल जानू॥१८॥
प्रभु मुद्रिका मेलि मुख माहीं। जलधि लांघि गये अचरज नाहीं॥१९॥
दुर्गम काज जगत के जेते। सुगम अनुग्रह तुम्हरे तेते॥२०॥`},{type:"heading",text:"चौपाई (२१-३०)"},{type:"paragraph",text:`राम दुआरे तुम रखवारे। होत न आज्ञा बिनु पैसारे॥२१॥
सब सुख लहै तुम्हारी सरना। तुम रच्छक काहू को डर ना॥२२॥
आपन तेज सम्हारो आपै। तीनों लोक हाँक तें काँपै॥२३॥
भूत पिसाच निकट नहिं आवै। महाबीर जब नाम सुनावै॥२४॥
नासै रोग हरै सब पीरा। जपत निरंतर हनुमत बीरा॥२५॥
संकट तें हनुमान छुड़ावै। मन क्रम बचन ध्यान जो लावै॥२६॥
सब पर राम तपस्वी राजा। तिन के काज सकल तुम साजा॥२७॥
और मनोरथ जो कोई लावै। सोइ अमित जीवन फल पावै॥२८॥
चारों जुग परताप तुम्हारा। है परसिद्ध जगत उजियारा॥२९॥
साधु संत के तुम रखवारे। असुर निकंदन राम दुलारे॥३०॥`},{type:"heading",text:"चौपाई (३१-४०)"},{type:"paragraph",text:`अष्ट सिद्धि नौ निधि के दाता। अस बर दीन जानकी माता॥३१॥
राम रसायन तुम्हरे पासा। सदा रहो रघुपति के दासा॥३२॥
तुम्हरे भजन राम को पावै। जनम जनम के दुख बिसरावै॥३३॥
अन्त काल रघुबर पुर जाई। जहाँ जन्म हरिभक्त कहाई॥३४॥
और देवता चित्त न धरई। हनुमत सेइ सर्ब सुख करई॥३५॥
संकट कटै मिटै सब पीरा। जो सुमिरै हनुमत बलबीरा॥३६॥
जय जय जय हनुमान गोसाईं। कृपा करहु गुरुदेव की नाईं॥३७॥
जो सत बार पाठ कर कोई। छूटहि बंदि महा सुख होई॥३८॥
जो यह पढ़ै हनुमान चालीसा। होय सिद्धि साखी गौरीसा॥३९॥
तुलसीदास सदा हरि चेरा। कीजै नाथ हृदय महँ डेरा॥४०॥`},{type:"heading",text:"दोहा"},{type:"verse",text:`पवनतनय संकट हरन, मंगल मूरति रूप।
राम लखन सीता सहित, हृदय बसहु सुर भूप॥`,translation:"हे संकट हरण गर्ने पवनपुत्र, मंगलमूर्ति हनुमानजी! तपाईं राम, लक्ष्मण र सीतासहित मेरो हृदयमा निवास गर्नुहोस्।"},{type:"paragraph",text:"नियमित रूपमा हनुमान चालीसा पाठ गर्नाले भय, रोग र संकटबाट मुक्ति मिल्छ। मंगलबार र शनिबार पाठ गर्नु विशेष फलदायक मानिन्छ।"}]},{id:"s6",title:"विष्णु सहस्रनाम (प्रमुख अंश)",subtitle:"महाभारत अनुशासन पर्व",tags:["स्तोत्र","धर्म","विष्णु"],content:[{type:"paragraph",text:"विष्णु सहस्रनाममा भगवान विष्णुका १००० नामहरूको स्तुति छ। यो भीष्म पितामहले युधिष्ठिरलाई उपदेश दिनुभएको थियो। यहाँ यसका प्रमुख श्लोकहरू दिइएको छ।"},{type:"heading",text:"ध्यानम्"},{type:"verse",text:`शान्ताकारं भुजगशयनं पद्मनाभं सुरेशं
विश्वाधारं गगनसदृशं मेघवर्णं शुभाङ्गम्।
लक्ष्मीकान्तं कमलनयनं योगिभिर्ध्यानगम्यं
वन्दे विष्णुं भवभयहरं सर्वलोकैकनाथम्॥`,translation:"शान्त आकार भएका, शेषनागको ओछ्यानमा सुत्ने, नाभिमा कमल भएका, देवताहरूका स्वामी, सम्पूर्ण विश्वको आधार, आकाश जस्तै विशाल, बादल जस्तै श्यामवर्ण, सुन्दर अंग भएका, लक्ष्मीका पति, कमल जस्तै आँखा भएका, योगीहरूले ध्यानद्वारा जान्न सक्ने, संसारको भय हटाउने, सबै लोकका एकमात्र स्वामी भगवान विष्णुलाई म वन्दना गर्छु।"},{type:"heading",text:"सहस्रनाम स्तोत्र आरम्भ"},{type:"verse",text:`विश्वं विष्णुर्वषट्कारो भूतभव्यभवत्प्रभुः।
भूतकृद्भूतभृद्भावो भूतात्मा भूतभावनः॥१॥
पूतात्मा परमात्मा च मुक्तानां परमा गतिः।
अव्ययः पुरुषः साक्षी क्षेत्रज्ञोऽक्षर एव च॥२॥
योगो योगविदां नेता प्रधानपुरुषेश्वरः।
नारसिंहवपुः श्रीमान् केशवः पुरुषोत्तमः॥३॥`,translation:"उहाँ सम्पूर्ण विश्व हुनुहुन्छ, विष्णु, वषट्कार, भूत, वर्तमान र भविष्यका स्वामी, जीवहरूको सृष्टि गर्ने, पोषण गर्ने, सबैको आत्मा, र सबैलाई उत्पन्न गर्ने हुनुहुन्छ। उहाँ पवित्र आत्मा, परमात्मा, मुक्त पुरुषहरूको परम गति, अविनाशी, साक्षी, र पुरुषोत्तम हुनुहुन्छ।"},{type:"heading",text:"फलश्रुति (अन्तिम श्लोक)"},{type:"verse",text:`आर्तः विषण्णः शिथिलश्च भीतः
घोरेषु च व्याधिषु वर्तमानः।
सङ्कीर्त्य नारायणशब्दमात्रं
विमुक्तदुःखः सुखितो भवति॥`,translation:'दुःखी, उदास, कमजोर, डराएको, वा भयंकर रोगले ग्रस्त मानिसले "नारायण" शब्दको मात्र कीर्तन गर्दा पनि सबै दुःखबाट मुक्त भई सुखी हुन्छ।'},{type:"verse",text:`नमो स्त्वनन्ताय सहस्रमूर्तये
सहस्रपादाक्षिशिरोरुबाहवे।
सहस्रनाम्ने पुरुषाय शाश्वते
सहस्रकोटियुगधारिणे नमः॥`,translation:"अनन्त, हजारौं मूर्ति भएका, हजारौं पाउ, आँखा, शिर र हात भएका, हजारौं नाम भएका, शाश्वत पुरुष, र हजारौं करोड युगहरू धारण गर्ने भगवानलाई नमस्कार छ।"},{type:"paragraph",text:"विष्णु सहस्रनामको पाठ गर्नाले पाप, रोग र भय नष्ट हुन्छ। यसले शान्ति, सम्पत्ति र मोक्ष प्रदान गर्छ।"}]},{id:"s7",title:"आदित्य हृदय स्तोत्रम्",subtitle:"वाल्मीकि रामायण",tags:["स्तोत्र","धर्म","सूर्य"],content:[{type:"paragraph",text:"रावणसँगको युद्धमा राम थकित हुँदा ऋषि अगस्त्यले उहाँलाई यो स्तोत्र पाठ गर्न सल्लाह दिनुभएको थियो। यसको पाठले विजय, शक्ति र स्वास्थ्य प्राप्त हुन्छ।"},{type:"heading",text:"अगस्त्य उवाच"},{type:"verse",text:`राम राम महाबाहो शृणु गुह्यं सनातनम्।
येन सर्वानरीन्वत्स समरे विजयिष्यसि॥१॥
आदित्यहृदयं पुण्यं सर्वशत्रुविनाशनम्।
जयावहं जपं नित्यमक्षयं परमं शिवम्॥२॥`,translation:"हे महाबाहु राम! यो सनातन गोप्य रहस्य सुन, जसको प्रभावले तिमी युद्धमा सबै शत्रुहरूलाई जित्नेछौ। यो आदित्य हृदय अत्यन्त पवित्र, सबै शत्रु नाश गर्ने, विजय दिलाउने, अविनाशी र परम कल्याणकारी छ।"},{type:"heading",text:"सूर्य स्तुति"},{type:"verse",text:`रश्मिमन्तं समुद्यन्तं देवासुरनमस्कृतम्।
पूजयस्व विवस्वन्तं भास्करं भुवनेश्वरम्॥
सर्वदेवात्मको ह्येष तेजस्वी रश्मिभावनः।
एष देवासुरगणाँल्लोकान् पाति गभस्तिभिः॥`,translation:"किरणयुक्त, उदय हुने, देव र असुरहरूद्वारा नमस्कृत, प्रकाशमान, भुवनेश्वर सूर्यदेवको पूजा गर। यी सम्पूर्ण देवताहरूका आत्मा हुन्, तेजिला छन्, र आफ्ना किरणहरूद्वारा सम्पूर्ण लोकको पालन गर्छन्।"},{type:"heading",text:"सूर्यका नामहरू"},{type:"verse",text:`आदित्यः सविता सूर्यः खगः पूषा गभस्तिमान्।
सुवर्णसदृशो भानुर्हिरण्यरेता दिवाकरः॥
हरिदश्वः सहस्रार्चिः सप्तसप्तिर्मरीचिमान्।
तिमिरोन्मथनः शम्भुस्त्वष्टा मार्तण्ड अंशुमान्॥`,translation:"आदित्य, सविता, सूर्य, खग, पूषा, गभस्तिमान, भानु, हिरण्यरेता, दिवाकर, हरिदश्व, सहस्रार्चि, सप्तसप्ति, मरीचिमान, तिमिरोन्मथन, शम्भु, मार्तण्ड र अंशुमान — यी सबै सूर्यकै नाम हुन्।"},{type:"heading",text:"फलश्रुति"},{type:"verse",text:`एनमापत्सु कृच्छ्रेषु कान्तारेषु भयेषु च।
कीर्तयन् पुरुषः कश्चिन्नावसीदति राघव॥`,translation:"हे राघव! विपत्तिमा, कष्टमा, घोर जंगलमा वा कुनै पनि डरलाग्दो परिस्थितिमा सूर्यको कीर्तन गर्ने मानिस कहिल्यै दुःखी वा पराजित हुँदैन।"},{type:"paragraph",text:"रामले यो स्तोत्र तीन पटक पाठ गरी आचमन गरेपछि नयाँ ऊर्जा प्राप्त गर्नुभयो र रावणको वध गर्नुभयो। आइतबारको दिन यसको पाठ विशेष फलदायक छ।"}]}],i=[{id:"p1",eventDate:{type:"LUNAR",month:1,paksha:"shukla",tithi:3,approxBsDay:18},title:"अक्षय तृतीया",tags:["चाडपर्व","धर्म","संस्कृति"],content:[{type:"paragraph",text:'वैशाख शुक्ल तृतीयाका दिन मनाइने अक्षय तृतीया हिन्दु धर्ममा अत्यन्त शुभ दिन मानिन्छ। "अक्षय" शब्दको अर्थ "कहिल्यै क्षय नहुने" वा "नास नहुने" हो। यस दिन गरिएको दान, धर्म, जप र तपको फल कहिल्यै नाश हुँदैन भन्ने शास्त्रीय मान्यता छ। यसै दिनबाट सत्ययुगको सुरुवात भएको मानिन्छ र भगवान परशुरामको अवतार पनि यसै तिथिमा भएको विश्वास गरिन्छ। यो दिन विवाह, गृहप्रवेश वा नयाँ व्यवसाय सुरु गर्नका लागि साइत हेर्नु नपर्ने स्वयं सिद्ध मुहूर्तिको रूपमा लिइन्छ।'},{type:"image",src:t.akshayaTritiya,alt:"Akshaya Tritiya Puja"},{type:"heading",text:"महत्व र विधि"},{type:"paragraph",text:"गर्मी यामको सुरुवात हुने भएकाले यस दिन शरीरलाई शीतलता प्रदान गर्ने खानेकुराहरू खाने र दान गर्ने परम्परा छ। विशेषगरी जौको सातु र चिसो सर्वत (चिनी वा सख्खर पानी) दान गरेर मात्र खाने चलन छ। यस दिन सुन वा चाँदी किन्दा लक्ष्मी स्थिर रहन्छिन् भन्ने जनविश्वास पनि छ।"},{type:"heading",text:"मुख्य गतिविधिहरू"},{type:"list",items:["जौको सातु र सर्वत खाने","शीतल खानेकुरा दान गर्ने","नयाँ कामको थालनी गर्ने","परशुराम जयन्ती मनाउने"]}]},{id:"p2",eventDate:{type:"BS",month:3,day:15,approxBsDay:15},title:"असार १५ (धान दिवस)",tags:["चाडपर्व","संस्कृति","प्रकृति"],content:[{type:"paragraph",text:'नेपाल एक कृषि प्रधान देश भएकोले असार १५ लाई राष्ट्रिय धान दिवस तथा रोपाईँ जात्राको रूपमा उल्लासका साथ मनाइन्छ। "मानो रोपेर मुरी उब्जाउने" समयको रूपमा लिइने यो दिन कृषकहरूको लागि वर्षकै सबैभन्दा व्यस्त र रमाइलो दिन हो। खेतका गराहरूमा पञ्चेबाजा बजाउँदै, असारे गीत गाउँदै र हिलो छ्यापाछ्याप गरेर यो पर्व मनाइन्छ।'},{type:"image",src:t.paddyPlantation,alt:"Paddy Plantation"},{type:"heading",text:"दहि चिउरा खाने दिन"},{type:"paragraph",text:"कामको चटारोका बीच शरीरलाई शक्ति र शीतलता दिन दहि र चिउरा खाने विशेष परम्परा छ। यसले नेपाली संस्कृति र कृषि कर्मको संयोजनलाई झल्काउँछ।"},{type:"list",items:["धान रोप्ने","हिलो खेल्ने","असारे गीत गाउने","दहि-चिउरा खाने"]}]},{id:"p3",eventDate:{type:"LUNAR",month:3,paksha:"shukla",tithi:15,approxBsDay:15},title:"गुरु पूर्णिमा",tags:["चाडपर्व","संस्कृति","शिक्षा"],content:[{type:"paragraph",text:'असार शुक्ल पूर्णिमाको दिन गायत्री मन्त्रका रचयिता, चार वेदका व्याख्याता र अठार पुराणका लेखक महर्षि वेदव्यासको जन्म जयन्तीको रूपमा गुरु पूर्णिमा मनाइन्छ। संस्कृतमा "गु" को अर्थ अन्धकार र "रु" को अर्थ प्रकाश हो; तसर्थ अन्धकारबाट उज्यालोतर्फ डोर्याउने व्यक्ति नै गुरु हुन्।'},{type:"image",src:t.guruPurnima,alt:"Guru Purnima"},{type:"heading",text:"सम्मान र समर्पण"},{type:"paragraph",text:"यस दिन विद्यालय, क्याम्पस र विभिन्न संघ-संस्थाहरूमा विद्यार्थीहरूले आफ्ना गुरु-गुरुआमाहरूलाई फूलमाला, उपहार र मिष्ठान्न भोजन अर्पण गरी आदर सम्मान व्यक्त गर्छन्। गुरुको मन्त्र लिने र दीक्षा ग्रहण गर्ने उत्तम दिन पनि यही हो।"},{type:"list",items:["वेदव्यासको पूजा","गुरुलाई उपहार अर्पण","दीक्षा ग्रहण","सांस्कृतिक इभेन्ट"]}]},{id:"p4",eventDate:{type:"LUNAR",month:6,paksha:"krishna",tithi:8,approxBsDay:8},title:"जितिया पर्व",tags:["चाडपर्व","संस्कृति","नारी"],content:[{type:"paragraph",text:"जितिया पर्व विशेषगरी तराई-मधेशका थारु तथा मैथिली समुदायका महिलाहरूले आफ्ना सन्तानको दीर्घायु, सुस्वास्थ्य र प्रगतिको कामना गर्दै मनाउने कठोर व्रत हो। यो पर्व आश्विन कृष्ण पक्षको सप्तमी, अष्टमी र नवमी गरी तीन दिनसम्म मनाइन्छ।"},{type:"image",src:t.jitiyaParva,alt:"Jitiya Festival"},{type:"heading",text:"कठोर व्रत विधि"},{type:"paragraph",text:'यसलाई "जिमूतवाहन" व्रत पनि भनिन्छ। पहिलो दिन "नहाय-खाय", दोस्रो दिन "खरजितिया" (निर्जल उपवास) र तेस्रो दिन व्रत समापन गरिन्छ। व्रत बस्दा ३६ घण्टासम्म पानी पनि नपिई बस्नुपर्ने परम्परा छ।'},{type:"list",items:["नहाय-खाय (चोखो खाने)","जिमूतवाहनको पूजा","निर्जल उपवास","सन्तानको दीर्घायु कामना"]}]},{id:"p5",eventDate:{type:"LUNAR",month:7,paksha:"shukla",tithi:15,approxBsDay:30},title:"सामा चकेवा",tags:["चाडपर्व","संस्कृति","कला"],content:[{type:"paragraph",text:"सामा चकेवा तराई क्षेत्रमा दिदीबहिनी र दाजुभाइबीचको प्रेमको प्रतीकको रूपमा मनाइने लोक पर्व हो। यो छठ पर्वको लगत्तै सुरु भई कार्तिक पूर्णिमासम्म मनाइन्छ। द्वापर युगमा कृष्णकी छोरी सामा र उनका पति चकेवाको कथामा आधारित यो पर्वमा माटोका मूर्तिहरू बनाएर खेलिन्छ।"},{type:"image",src:t.samaChakeva,alt:"Sama Chakeva"},{type:"heading",text:"मूर्ति र विसर्जन"},{type:"paragraph",text:"दिदीबहिनीहरूले माटोका विभिन्न रङ्गीचङ्गी मूर्तिहरू (सामा, चकेवा, सातभैया, चुगला आदि) बनाउँछन्। राति समूहमा बसेर लोकगीत गाउँदै यी मूर्तिहरूसँग खेल्छन् र अन्तिम दिन नदी वा पोखरीमा विसर्जन गर्छन्।"},{type:"list",items:["माटोका मूर्ति बनाउने","लोकगीत गाउने","दाजुभाइलाई आशिष्","मूर्ति विसर्जन"]}]},{id:"p6",eventDate:{type:"BS",month:3,day:29,approxBsDay:29},title:"भानु जयन्ती",tags:["चाडपर्व","साहित्य","इतिहास"],content:[{type:"paragraph",text:"नेपाली भाषाका आदिकवि भानुभक्त आचार्यको जन्म जयन्ती हरेक वर्ष असार २९ गते मनाइन्छ। संस्कृत भाषामा रहेको जटिल रामायणलाई सरल नेपाली भाषामा अनुवाद गरी आम नेपालीको जिब्रोमा झुन्ड्याउन भानुभक्तले अतुलनीय योगदान पुर्‍याएका छन्।"},{type:"image",src:t.bhanubhaktaAcharya,alt:"Bhanubhakta Acharya"},{type:"heading",text:"साहित्यिक उत्सव"},{type:"paragraph",text:"देश तथा विदेशमा रहेका नेपाली भाषीहरूले प्रभातफेरी, कविता वाचन, रामायण पाठ र साहित्यिक गोष्ठीहरूको आयोजना गरी यो दिवस मनाउँछन्। घाँसीको प्रेरणाबाट रामायण लेख्न सुरु गरेका भानुभक्तको सम्झनामा माल्यार्पण गरिन्छ।"},{type:"list",items:["रामायण पाठ","कविता वाचन","साहित्यिक गोष्ठी","माल्यार्पण"]}]},{id:"p7",eventDate:{type:"BS",month:4,day:1,approxBsDay:1},title:"साउने संक्रान्ति",tags:["चाडपर्व","प्रकृति","संस्कृति"],content:[{type:"paragraph",text:"सूर्य कर्कट राशिमा प्रवेश गर्ने दिनलाई साउने वा कर्कट संक्रान्ति भनिन्छ। यो दिनबाट सूर्य दक्षिणतर्फ ढल्कने हुँदा दिन छोटो र रात लामो हुन थाल्छ। यो बर्खायामको हिलो मैलोबाट लाग्न सक्ने रोगव्याधि हटाउने पर्व हो।"},{type:"image",src:t.sauneSankranti,alt:"Saune Sankranti"},{type:"heading",text:"लुतो फाल्ने विधि"},{type:"paragraph",text:'साँझपख घरको आँगनमा कुरिलो, कुकरडाइनो, भलायो, तितेपाती आदि बालेर "लुतो लैजा" भन्दै अगुल्टो चारै दिशामा फालिन्छ। यसलाई कण्डारक पूजा पनि भनिन्छ। विवाहित छोरीचेलीलाई माइत बोलाएर खुवाउने चलन पनि छ।'},{type:"list",items:["कण्डारक पूजा","लुतो फाल्ने","अगुल्टो प्रहार","ज्वाइँ-चेली निम्त्याउने"]}]},{id:"p8",eventDate:{type:"BS",month:11,day:7,approxBsDay:7},title:"राष्ट्रिय प्रजातन्त्र दिवस",tags:["इतिहास","राष्ट्रिय"],content:[{type:"paragraph",text:"विक्रम सम्वत् २००७ साल फागुन ७ गते १०४ वर्ष लामो जहाँनिया राणा शासन अन्त्य भई देशमा प्रजातन्त्र स्थापना भएको सम्झनामा यो दिवस मनाइन्छ। यो आधुनिक नेपालको राजनीतिक इतिहासको एक कोसेढुङ्गा हो।"},{type:"image",src:t.prajatantraDiwas,alt:"Prajatantra Diwas"},{type:"heading",text:"समारोह"},{type:"paragraph",text:"टुँडिखेलमा नेपाली सेना, नेपाल प्रहरी र विभिन्न संघसंस्थाहरूले मार्च पास र सांस्कृतिक झाँकी प्रस्तुत गर्छन्। सरकारले यस दिन सार्वजनिक बिदा दिन्छ र देशभर दीपावली गरी मनाइन्छ।"},{type:"list",items:["सैनिक मञ्चमा इभेन्ट","प्रभातफेरी","दीप प्रज्वलन","शुभकामना आदानप्रदान"]}]},{id:"p9",eventDate:{type:"BS",month:2,day:15,approxBsDay:15},title:"गणतन्त्र दिवस",tags:["इतिहास","राष्ट्रिय"],content:[{type:"paragraph",text:"विक्रम सम्वत् २०६५ साल जेठ १५ गते संविधानसभाको पहिलो बैठकले नेपाललाई संघीय लोकतान्त्रिक गणतन्त्र घोषणा गरेको ऐतिहासिक दिनको सम्झनामा यो दिवस मनाइन्छ। यसले २४० वर्ष लामो राजतन्त्रको अन्त्य गरेको थियो।"},{type:"image",src:t.republicDay,alt:"Republic Day Rally"},{type:"heading",text:"महत्व"},{type:"paragraph",text:"यो नेपाली जनता सार्वभौमसत्ता सम्पन्न भएको दिन हो। यस दिन राष्ट्रपतिद्वारा कैदीहरूको सजाय माफी मिनाहा गर्ने, विभूषण प्रदान गर्ने र विशेष समारोह आयोजना गर्ने गरिन्छ।"},{type:"list",items:["गणतन्त्र घोषणा स्मरण","कैदी माफी मिनाहा","विभूषण वितरण","दिपावली"]}]},{id:"p10",eventDate:{type:"LUNAR",month:7,paksha:"shukla",tithi:15,approxBsDay:30},title:"मनि रिम्दु (शेर्पा पर्व)",tags:["चाडपर्व","संस्कृति","बौद्ध"],content:[{type:"paragraph",text:"मनि रिम्दु सोलुखुम्बुको खुम्बु क्षेत्रमा मनाइने शेर्पा समुदायको सबैभन्दा ठूलो र महत्त्वपूर्ण पर्व हो। यो विशेष गरी तेङ्बोचे गुम्बामा १९ दिनसम्म मनाइन्छ। यो पर्वले बौद्ध धर्मको विजय र दुष्ट शक्तिहरूको पराजयलाई जनाउँछ।"},{type:"image",src:t.maniRimdu,alt:"Mani Rimdu"},{type:"heading",text:"छम नाच"},{type:"paragraph",text:'लामाहरूले रङ्गीचङ्गी मुखुन्डो लगाएर तान्त्रिक नृत्य (छम) प्रस्तुत गर्छन्। हजारौं पर्यटक र स्थानीयहरू यो जात्रा हेर्न भेला हुन्छन्। यसमा "मनि" भन्नाले मन्त्र र "रिम्दु" भन्नाले चक्की वा गोलो वस्तु भन्ने बुझिन्छ।'},{type:"list",items:["तान्त्रिक नृत्य (छम)","मन्त्र जप","गुम्बा पूजा","सांस्कृतिक झाँकी"]}]},{id:"p11",eventDate:{type:"BS",month:2,day:1,approxBsDay:1},title:"तिजी पर्व (मुस्ताङ)",tags:["चाडपर्व","संस्कृति","बौद्ध"],content:[{type:"paragraph",text:'उपल्लो मुस्ताङको लो-मान्थाङमा मनाइने ऐतिहासिक र सांस्कृतिक पर्व हो। "तिजी" शब्द "तेन्ची" बाट आएको हो जसको अर्थ "विश्व शान्ति" हुन्छ। यो पर्व तीन दिनसम्म मनाइन्छ र यसले गुरु रिन्पोक्षेको अवतार मानिने दोर्जी जोनुले राक्षस बाबुलाई परास्त गरेको कथा बोकेको छ।'},{type:"image",src:t.tijiFestival,alt:"Tiji Festival"},{type:"heading",text:"विशेषता"},{type:"paragraph",text:"रातो रङका भेषभूषामा सजिएका लामाहरूले दरबार अगाडिको चोकमा तरबार नचाउँदै प्राचीन नृत्य देखाउँछन्। यो मुस्ताङको पर्यटनको मुख्य आकर्षण पनि हो।"},{type:"list",items:["दोर्जी जोनुको नाच","राक्षस दहन","विश्व शान्ति पूजा","पारम्परिक वेशभूषा"]}]},{id:"p12",eventDate:{type:"LUNAR",month:9,paksha:"shukla",tithi:15,approxBsDay:30},title:"श्रीस्वस्थानी व्रत",tags:["चाडपर्व","धर्म","नारी"],content:[{type:"paragraph",text:"पौष शुक्ल पूर्णिमादेखि माघ शुक्ल पूर्णिमासम्म एक महिना चल्ने यो व्रतमा भगवान शिव र शक्ति (देवी) को पूजा गरिन्छ। प्रत्येक घरमा साँझपख श्रीस्वस्थानी परमेश्वरीको कथा वाचन गर्ने परम्परा छ।"},{type:"image",src:t.swasthaniKatha,alt:"Swasthani Katha"},{type:"heading",text:"शालीनदी मेला"},{type:"paragraph",text:"काठमाडौंको साँखुस्थित शालीनदीमा एक महिनासम्म मेला लाग्छ। व्रतालुहरूले एक छाक मात्र सात्विक भोजन खाने, चिसो पानीमा स्नान गर्ने र महिना दिनसम्म कठोर नियम पालना गर्छन्।"},{type:"list",items:["स्वस्थानी कथा वाचन","शालीनदी स्नान","एक छाक भोजन","शिव-शक्ति पूजा"]}]},{id:"p13",eventDate:{type:"LUNAR",month:10,paksha:"shukla",tithi:15,approxBsDay:30},title:"माघे पूर्णिमा",tags:["चाडपर्व","धर्म","संस्कृति"],content:[{type:"paragraph",text:'माघ शुक्ल पूर्णिमालाई माघी पूर्णिमा पनि भनिन्छ। यो श्रीस्वस्थानी व्रतको समापन हुने दिन हो। यस दिनलाई जलको पूजा गर्ने विशेष दिनको रूपमा लिइन्छ। तराईमा यस दिनलाई विशेष रूपमा "सन्त रविदास जयन्ती" का रूपमा पनि मनाइन्छ।'},{type:"image",src:t.maghePurnima,alt:"Maghe Purnima"},{type:"heading",text:"स्नान र दान"},{type:"paragraph",text:'यस दिन काठमाडौं उपत्यकाका नेवार समुदायले "सिलाः चह्रे" को रूपमा पनि मनाउँछन्। विभिन्न नदीनाला र त्रिवेणीहरूमा मेला लाग्छ र भक्तजनहरूले पवित्र स्नान गरी दान दक्षिणा गर्छन्।'},{type:"list",items:["पवित्र स्नान","स्वस्थानी समापन","रविदास जयन्ती","सिलाः चह्रे"]}]},{id:"p14",eventDate:{type:"LUNAR",month:6,paksha:"shukla",tithi:15,approxBsDay:30},title:"कोजाग्रत पूर्णिमा",tags:["चाडपर्व","धर्म","संस्कृति"],content:[{type:"paragraph",text:'बडादशैँको अन्तिम दिन अर्थात् आश्विन शुक्ल पूर्णिमालाई कोजाग्रत पूर्णिमा भनिन्छ। "कोजाग्रत" को अर्थ "को जागेको छ?" भन्ने हुन्छ। जनविश्वास अनुसार यस रात धनधान्यकी देवी महालक्ष्मी पृथ्वीको परिक्रमा गर्न आउँछिन् र जो रातभर जाग्राम बस्छ, उसैलाई धन प्रदान गर्छिन्।'},{type:"image",src:t.kojagratPurnima,alt:"Kojagrat Purnima"},{type:"heading",text:"दशैँ समापन"},{type:"paragraph",text:"यस दिन दशैँको टीका र जमरा विसर्जन गरिन्छ। आकाशमा बलेका रङ्गीचङ्गी आकाशदीप (बत्ती) उडाउने र जुवातास खेलेर रात काट्ने परम्परा पनि समाजमा विद्यमान छ।"},{type:"list",items:["लक्ष्मी पूजा","जाग्राम बस्ने","आकाशदीप उडाउने","जमरा विसर्जन"]}]},{id:"p15",eventDate:{type:"LUNAR",month:5,paksha:"shukla",tithi:1,approxBsDay:15},title:"अतवारी (थारु पर्व)",tags:["चाडपर्व","संस्कृति","प्रकृति"],content:[{type:"paragraph",text:"अतवारी थारु समुदायको माघी पछिको दोस्रो ठूलो पर्व हो। यो भदौ वा असोज महिनाको आइतबार (अतवार) पर्ने भएकाले यसलाई अतवारी भनिएको हो। यो पर्व महाभारतका पात्र भीम (भेंवा) को पूजा गरी मनाइन्छ।"},{type:"image",src:t.tharuCulture,alt:"Tharu Aatwari"},{type:"heading",text:"अग्रासन"},{type:"paragraph",text:'दाजुभाइले दिदीबहिनीको सुरक्षा र दीर्घायुको कामना गर्दै व्रत बस्छन्। "अग्रासन" (विशेष कोसेली) लिएर विवाहित चेलीबेटीको घरमा जाने चलन छ, जसले पारिवारिक सम्बन्धलाई प्रगाढ बनाउँछ।'},{type:"list",items:["भीमसेन पूजा","व्रत बस्ने","अग्रासन दिने","सूर्य पूजा"]}]},{id:"p16",eventDate:{type:"BS",month:1,day:2,approxBsDay:2},title:"सिन्दुर जात्रा",tags:["चाडपर्व","संस्कृति","जात्रा"],content:[{type:"paragraph",text:'भक्तपुरको मध्यपुर ठिमीमा नयाँ वर्ष (बैशाख १ र २) को अवसरमा ३२ खटको जात्रासँगै भव्य सिन्दुर जात्रा मनाइन्छ। यसलाई स्थानीय भाषामा "सुथः सिया" भनिन्छ। यो बिस्केट जात्राकै एक विशिष्ट र रोमाञ्चक भाग हो।'},{type:"image",src:t.sindurJatra,alt:"Sindur Jatra"},{type:"heading",text:"रङ्गीन उत्सव"},{type:"paragraph",text:"सुन्तला रङको सिन्दुर एक-अर्कालाई छ्यापेर, धिमे बाजाको तालमा नाच्दै, र विभिन्न देवताका खटहरूलाई बोकेर नगर परिक्रमा गराइन्छ। बालकुमारी मन्दिर परिसरमा हुने यो जात्रामा सिन्दुरले आकाश नै रङ्गीन बन्छ।"},{type:"list",items:["सिन्दुर खेल्ने","खट जात्रा","धिमे बाजा","नगर परिक्रमा"]}]},{id:"p17",eventDate:{type:"LUNAR",month:4,paksha:"shukla",tithi:1,approxBsDay:16},title:"गुँला पर्व",tags:["चाडपर्व","संस्कृति","बौद्ध"],content:[{type:"paragraph",text:'नेवार बौद्ध सम्प्रदायमा श्रावण शुक्ल प्रतिपदादेखि भाद्र शुक्ल प्रतिपदासम्म एक महिना मनाइने पर्व हो। "गुँ" को अर्थ जङ्गल र "ला" को अर्थ महिना हो। यो वर्षावासको समय हो, जहाँ एकान्तमा बसेर ध्यान गरिन्छ।'},{type:"image",src:t.gunlaBajan,alt:"Gunla Bajan"},{type:"heading",text:"बाजा र परिक्रमा"},{type:"paragraph",text:"बिहान सबेरै गुँला बाजा बजाउँदै स्वयम्भू महाचैत्य र अन्य बिहारहरूको परिक्रमा गरिन्छ। यो महिनाभरि हिंसा नगर्ने, मद्यपान नगर्ने र दानपुण्य गर्ने गरिन्छ।"},{type:"list",items:["गुँला बाजा","स्वयम्भू परिक्रमा","ध्यान र पूजा","मद्यपान निषेध"]}]},{id:"p18",eventDate:{type:"LUNAR",month:4,paksha:"krishna",tithi:13,approxBsDay:28},title:"पञ्चदान (बौद्ध पर्व)",tags:["चाडपर्व","संस्कृति","बौद्ध","दान"],content:[{type:"paragraph",text:"पञ्चदान बौद्ध नेवारहरूको दान दिने मुख्य पर्व हो। यो गुँला महिनामा पर्छ। दीपंकर बुद्धलाई धान, चामल, गहुँ, नुन र पैसा गरी पाँच प्रकारका वस्तु दान गरिने भएकाले पञ्चदान भनिएको हो।"},{type:"image",src:t.panchaDan,alt:"Pancha Dan"},{type:"heading",text:"दान विधि"},{type:"paragraph",text:"घरघरबाट र बिहारहरूमा बज्राचार्य तथा शाक्य भिक्षुहरूलाई निमन्त्रणा गरी वा बाटोमा लामबद्ध भई श्रद्धापूर्वक दान दिइन्छ। ललितपुरको पञ्चदानमा विशाल बुद्धका मूर्तिहरू प्रदर्शन गरिन्छ।"},{type:"list",items:["दीपंकर बुद्ध पूजा","पाँच वस्तु दान","भिक्षु भोजन","मूर्ति प्रदर्शन"]}]},{id:"p19",eventDate:{type:"LUNAR",month:6,paksha:"shukla",tithi:6,approxBsDay:21},title:"शिकाली जात्रा (खोकना)",tags:["चाडपर्व","संस्कृति","जात्रा"],content:[{type:"paragraph",text:"ललितपुरको खोकना गाउँमा दशैँको समयमा (घटस्थापनादेखि) मनाइने यो अनौठो जात्रा हो। खोकनाबासीले दशैँ मनाउँदैनन्, त्यसको सट्टा उनीहरू शिकाली जात्रा (रुद्रायणी जात्रा) मनाउँछन्।"},{type:"image",src:t.shikaliJatra,alt:"Shikali Jatra"},{type:"heading",text:"मुखुन्डो नाच"},{type:"paragraph",text:"सेतो वस्त्र पहिरिएका धामीहरूले भद्रकाली, इन्द्रायणी लगायतका देवीदेवताको मुखुन्डो लगाएर नाच नाच्छन्। यो जात्रामा बलिको सट्टा काभ्रो (एक प्रकारको फल) को प्रयोग गरिन्छ।"},{type:"list",items:["रुद्रायणी पूजा","मुखुन्डो नाच","दशैँको विकल्प","काभ्रो बलि"]}]},{id:"p20",eventDate:{type:"LUNAR",month:7,paksha:"shukla",tithi:15,approxBsDay:30},title:"त्रिवेणी मेला",tags:["चाडपर्व","धर्म","तीर्थ"],content:[{type:"paragraph",text:"सुनसरी जिल्लाको बराह क्षेत्रमा कोशी र कोका नदीको सङ्गम (त्रिवेणी) मा लाग्ने यो मेला कार्तिक पूर्णिमाको दिन विशेष हुन्छ। भगवान विष्णुले बराह (सुँगुर) को अवतार लिएर हिरण्याक्ष राक्षसको वध गरेको स्थान मानिन्छ।"},{type:"image",src:t.triveniMela,alt:"Triveni Mela"},{type:"heading",text:"तीर्थ महत्व"},{type:"paragraph",text:"भारत र नेपालका विभिन्न स्थानबाट लाखौँ भक्तजनहरू यहाँ स्नान गर्न र वराह भगवानको दर्शन गर्न आउँछन्। यहाँ पितृ श्राद्ध गर्दा मोक्ष प्राप्त हुने विश्वास छ। यो नेपालका चार धाम मध्येको एक हो।"},{type:"list",items:["संगममा स्नान","बराह दर्शन","पितृ श्राद्ध","कार्तिक मेला"]}]},{id:"p21",eventDate:{type:"LUNAR",month:1,paksha:"shukla",tithi:9,approxBsDay:24},title:"सीता जयन्ती",tags:["चाडपर्व","धर्म","इतिहास"],content:[{type:"paragraph",text:"बैशाख शुक्ल नवमीका दिन आदर्श नारी तथा भगवान रामकी पत्नी सीता (जानकी) को जन्म जयन्ती मनाइन्छ। राजा जनकले हलो जोत्दा धर्तीबाट सीताको उत्पत्ति भएको विश्वास गरिन्छ।"},{type:"image",src:t.janakiMandir,alt:"Janaki Mandir"},{type:"heading",text:"जनकपुर उत्सव"},{type:"paragraph",text:"जानकी मन्दिरलाई दुलही झैँ सिङ्गारिन्छ। राम र सीताको कथा वाचन, भजन कीर्तन र विशेष पूजा गरिन्छ। सीताको त्याग, धैर्य र पतिव्रता धर्मको चर्चा गरिन्छ।"},{type:"list",items:["जानकी मन्दिर पूजा","रामायण पाठ","भजन कीर्तन","दीप प्रज्वलन"]}]},{id:"p22",eventDate:{type:"LUNAR",month:12,paksha:"shukla",tithi:15,approxBsDay:30},title:"हनुमान जयन्ती",tags:["चाडपर्व","धर्म","शक्ति"],content:[{type:"paragraph",text:"चैत्र शुक्ल पूर्णिमाको दिन भगवान शिवको ११औँ रुद्र अवतार मानिने महावीर हनुमानको जन्म जयन्ती मनाइन्छ। बल, बुद्धि र विद्याका खानी हनुमान रामभक्तिको सर्वोच्च उदाहरण हुन्।"},{type:"image",src:t.hanumanJayanti,alt:"Hanuman Jayanti"},{type:"heading",text:"पूजा विधि"},{type:"paragraph",text:"भक्तजनहरूले बिहानै उठेर स्नान गरी हनुमान चालिसा पाठ गर्छन्। मन्दिरहरूमा सिन्दुर र तेल अर्पण गरिन्छ (हनुमानलाई सिन्दुर मन पर्छ)। लड्डुको भोग लगाउने र रातो वस्त्र धारण गर्ने चलन छ।"},{type:"list",items:["हनुमान चालिसा पाठ","सिन्दुर अर्पण","लड्डु भोग","रातो वस्त्र धारण"]}]},{id:"p23",eventDate:{type:"LUNAR",month:5,paksha:"shukla",tithi:8,approxBsDay:23},title:"राधा अष्टमी",content:[{type:"paragraph",text:"भाद्र शुक्ल अष्टमीका दिन (कृष्ण जन्माष्टमीको १५ दिन पछि) राधा रानीको जन्म जयन्ती मनाइन्छ। कृष्ण बिना राधा र राधा बिना कृष्ण अपूरो मानिन्छन्। यो प्रेम र भक्तिको पर्व हो।"},{type:"image",src:t.radhaAshtami,alt:"Radha Ashtami"},{type:"heading",text:"छप्पन भोग"},{type:"paragraph",text:"कृष्ण प्रणामी र वैष्णव सम्प्रदायमा यसको ठूलो महत्त्व छ। भक्तजनहरूले व्रत बस्ने, राधा-कृष्णको लिला गान गर्ने र मन्दिरमा ५६ प्रकारका व्यञ्जन (छप्पन भोग) चढाउने गर्छन्।"},{type:"list",items:["राधा पूजा","छप्पन भोग","लिला कीर्तन","उपवास"]}]},{id:"p24",eventDate:{type:"LUNAR",month:1,paksha:"shukla",tithi:15,approxBsDay:30},title:"चण्डी पूर्णिमा (उभौली)",content:[{type:"paragraph",text:'वैशाख शुक्ल पूर्णिमालाई चण्डी पूर्णिमा पनि भनिन्छ। यो दिन किरात राई समुदायले "उभौली" पर्वका रूपमा साकेला चण्डी नाच नाचेर मनाउँछन्। यो बुद्ध जयन्तीकै दिन पर्छ तर किरात संस्कृतिमा यसको छुट्टै र विशिष्ट स्थान छ।'},{type:"image",src:t.sakelaDance,alt:"Sakela Dance"},{type:"heading",text:"साकेला सिली"},{type:"paragraph",text:"अन्न बाली लगाउने समय भएकोले प्रकृतिको पूजा गरी राम्रो बालीनालीको कामना गरिन्छ। ढोल र झ्याम्टाको तालमा हात समाएर गोलो घेरामा नाच्ने साकेला सिली यो पर्वको मुख्य आकर्षण हो।"},{type:"list",items:["साकेला नाच","भूमि पूजा","पितृ स्मरण","ढोल झ्याम्टा वादन"]}]},{id:"p25",eventDate:{type:"BS",month:5,day:1,approxBsDay:1},title:"न्वागी (चेपाङ पर्व)",content:[{type:"paragraph",text:"न्वागी (छोनाम) चेपाङ समुदायको सबैभन्दा ठूलो धार्मिक पर्व हो। यो भदौ महिनामा नयाँ बाली पाकेपछि मनाइन्छ। आफ्ना पितृ र प्रकृतिलाई नयाँ अन्न नचढाई खाँदा अनिष्ट हुन्छ भन्ने विश्वास उनीहरूमा छ।"},{type:"heading",text:"पितृ पूजा"},{type:"paragraph",text:"झाँकी (पान्दे) ले रातभर ढ्याङ्ग्रो ठोकेर पितृ बोलाउने र घैया धान, पिँडालु, निबुवा आदि चढाउने गर्छन्। यो पर्वले चेपाङ समुदायको कृषि जीवनशैली र वनमा आधारित संस्कृतिलाई जीवित राखेको छ।"},{type:"list",items:["घैया धान चढाउने","पान्देको झाँकी","पितृ आवाहन","सामूहिक भोज"]}]},{id:"p26",eventDate:{type:"LUNAR",month:4,paksha:"shukla",tithi:15,approxBsDay:30},title:"यार्तुङ (मुस्ताङ)",content:[{type:"paragraph",text:'यार्तुङ मुस्ताङको मुक्तिनाथ क्षेत्रमा मनाइने सबैभन्दा रमाइलो चाड हो। यो जनै पूर्णिमाको आसपास तीन दिनसम्म मनाइन्छ। "यार" को अर्थ वर्षा र "तुङ" को अर्थ अन्त्य हो, अर्थात् वर्षायामको बिदाई र हिउँदको स्वागत गर्ने पर्व।'},{type:"image",src:t.yartung,alt:"Yartung Festival"},{type:"heading",text:"घोडा दौड"},{type:"paragraph",text:"यो पर्वको मुख्य आकर्षण घोडा दौड हो। स्थानीय युवाहरू परम्परागत पोसाकमा सजिएर घोडा दौडाउँछन्, जमिनमा राखिएको पैसा घोडाबाटै टिप्ने कला देखाउँछन्।"},{type:"list",items:["घोडा दौड प्रतियोगिता","स्याब्रू नाच","हिउँदको स्वागत","परम्परागत भोज"]}]},{id:"p27",eventDate:{type:"LUNAR",month:6,paksha:"shukla",tithi:11,approxBsDay:26},title:"भीमसेन जात्रा (दोलखा)",content:[{type:"paragraph",text:'दोलखा बजारमा अवस्थित प्रसिद्ध भीमसेनको जात्रा बडादशैँको एकादशीका दिन भव्य रूपमा मनाइन्छ। दोलखा भीमसेनलाई "व्यापारीहरूको इष्टदेव" मानिन्छ। यहाँको मूर्ति पसिना आउँदा देशमा अनिष्ट हुन्छ भन्ने विश्वास गरिन्छ।'},{type:"image",src:t.dolakhaBhimsen,alt:"Dolakha Bhimsen"},{type:"heading",text:"बजार परिक्रमा"},{type:"paragraph",text:"भीमसेनको मूर्तिलाई खटमा राखेर बाजागाजासहित बजार परिक्रमा गराइन्छ। स्थानीय नेवार समुदायले यो जात्रालाई ठूलो उत्सवका रूपमा लिन्छन् र टाढा-टाढाबाट दर्शनार्थीहरू पुग्छन्।"},{type:"list",items:["मूर्ति खटयात्रा","पसिना पुछ्ने विधि","बलि पूजा","धार्मिक मेला"]}]},{id:"p28",eventDate:{type:"BS",month:8,day:1,approxBsDay:1},title:"गढीमाई मेला",content:[{type:"paragraph",text:"बारा जिल्लाको बरियारपुरमा लाग्ने गढीमाई मेला विश्वकै ठूलो धार्मिक मेलाहरू मध्ये एक हो। यो मेला हरेक ५-५ वर्षमा एकपटक (मंसिर महिनामा) लाग्छ। गढीमाई देवीले भक्तजनको मनोकामना पूरा गर्ने विश्वास गरिन्छ।"},{type:"heading",text:"भक्तजनको घुइँचो"},{type:"paragraph",text:"लाखौँ भक्तजनहरू, विशेषगरी भारतबाट, भाकल पूरा गर्न यहाँ आउँछन्। यहाँ बलिको परम्परा लामो समयदेखि चलिआएको छ, यद्यपि पछिल्लो समयमा शान्तिपूर्ण पूजा र नरिवल फुटाउने चलन पनि बढ्दो छ।"},{type:"list",items:["पञ्चवर्षीय मेला","भाकल पूरा गर्ने","दीप प्रज्वलन","बलि/नरिवल अर्पण"]}]},{id:"p29",eventDate:{type:"LUNAR",month:2,paksha:"shukla",tithi:10,approxBsDay:25},title:"खप्तड मेला (गंगा दशहरा)",content:[{type:"paragraph",text:"सुदूरपश्चिमको भू-स्वर्ग मानिने खप्तड राष्ट्रिय निकुञ्जमा जेठ महिनाको गंगा दशहरा तिथिमा भव्य मेला लाग्छ। यहाँ रहेको खप्तड बाबाको आश्रम र त्रिवेणी धाम धार्मिक रूपले पवित्र मानिन्छ।"},{type:"heading",text:"आध्यात्मिक यात्रा"},{type:"paragraph",text:"डोटी, अछाम, बझाङ र बाजुराको संगमस्थलमा पर्ने यो ठाउँमा भक्तजनहरू कठिन पैदल यात्रा गरेर पुग्छन्। देउडा खेल्ने र प्राकृतिक सुन्दरतामा रमाउने यो एक आध्यात्मिक र सांस्कृतिक यात्रा हो।"},{type:"list",items:["त्रिवेणी स्नान","खप्तड बाबा आश्रम दर्शन","देउडा नाच","प्रकृति भ्रमण"]}]},{id:"p30",eventDate:{type:"LUNAR",month:4,paksha:"shukla",tithi:14,approxBsDay:29},title:"बडिमालिका मेला",content:[{type:"paragraph",text:"बाजुरा जिल्लामा अवस्थित बडिमालिका भगवती शक्तिपीठहरू मध्ये एक प्रमुख मानिन्छ। जनै पूर्णिमाको अघिल्लो दिन (चतुर्दशी) यहाँ ठूलो मेला लाग्छ। समुद्री सतहबाट ४२०० मिटर उचाइमा रहेको यो मन्दिर पुग्न निकै कठिन तर रोमाञ्चक छ।"},{type:"image",src:t.badimalika,alt:"Badimalika"},{type:"heading",text:"पाटन यात्रा"},{type:"paragraph",text:"सतीदेवीको बायाँ कुम पतन भएको मानिने यस स्थानमा मागेको वरदान पूरा हुने विश्वास छ। यहाँ २२ पाटन (हरियाली चौर) हरू पार गरेर जानुपर्छ, जसको प्राकृतिक दृश्य अलौकिक हुन्छ।"},{type:"list",items:["शक्तिपीठ दर्शन","कठिन पदयात्रा","२२ पाटन अवलोकन","वरदान माग्ने"]}]},{id:"p31",eventDate:{type:"BS",month:7,day:25,approxBsDay:25},title:"फाल्गुनन्द जयन्ती",content:[{type:"paragraph",text:"किरात धर्मका महागुरु तथा राष्ट्रिय विभूति फाल्गुनन्द लिङ्देनको जन्म जयन्ती कार्तिक २५ गते मनाइन्छ। उहाँले पूर्वी नेपालको किरात समाजमा समाज सुधारकको रूपमा ठूलो योगदान पुर्‍याउनुभएको छ।"},{type:"image",src:t.falgunandaJayanti,alt:"Falgunanda Jayanti"},{type:"heading",text:"सत्य धर्म मुचुल्का"},{type:"paragraph",text:'उहाँले वि.सं. १९८८ मा १० बुँदे "सत्य धर्म मुचुल्का" जारी गरी छोरीचेलीलाई बेच्न नपाइने, मद्यपान र मासु सेवन कम गर्ने जस्ता सामाजिक सुधारका नियमहरू बनाउनुभएको थियो।'},{type:"list",items:["किरात धर्म प्रवचन","सत्य धर्म मुचुल्का स्मरण","शाकाहारी भोजन","माल्यार्पण"]}]},{id:"p32",eventDate:{type:"BS",month:5,day:29,approxBsDay:29},title:"राष्ट्रिय बाल दिवस",content:[{type:"paragraph",text:"नेपालमा भदौ २९ गते राष्ट्रिय बाल दिवस मनाइन्छ। नेपालले बाल अधिकार सम्बन्धी महासन्धि अनुमोदन गरेको दिनको सम्झनामा यो दिवस मनाउन थालिएको हो।"},{type:"heading",text:"बाल अधिकार"},{type:"paragraph",text:"बालबालिकाको हक, हित र अधिकार संरक्षणका लागि जनचेतना जगाउनु यसको मुख्य उद्देश्य हो। विद्यालयहरूमा खेलकुद, हाजिरीजवाफ र सांस्कृतिक इभेन्टहरू आयोजना गरिन्छन्।"},{type:"list",items:["सचेतनामूलक र्‍याली","खेलकुद प्रतियोगिता","सांस्कृतिक इभेन्ट","पुरस्कार वितरण"]}]},{id:"p33",eventDate:{type:"BS",month:11,day:24,approxBsDay:24},title:"अन्तर्राष्ट्रिय नारी दिवस",content:[{type:"paragraph",text:"मार्च ८ का दिन विश्वभरि जस्तै नेपालमा पनि अन्तर्राष्ट्रिय नारी दिवस मनाइन्छ। यो महिलाहरूको सामाजिक, आर्थिक, सांस्कृतिक र राजनीतिक उपलब्धिहरूको उत्सव मनाउने दिन हो।"},{type:"image",src:t.womensDay,alt:"Womens Day"},{type:"heading",text:"समानताको आवाज"},{type:"paragraph",text:"महिला सशक्तीकरण, लैङ्गिक समानता र महिला हिंसा अन्त्यको लागि आवाज उठाउने दिन हो। विभिन्न सरकारी तथा गैर-सरकारी संस्थाहरूले गोष्ठी र सम्मान इभेन्टहरू आयोजना गर्छन्।"},{type:"list",items:["अधिकार र्‍याली","अन्तरक्रिया इभेन्ट","महिला सम्मान","लैङ्गिक समानता बहस"]}]},{id:"p34",eventDate:{type:"LUNAR",month:7,paksha:"shukla",tithi:15,approxBsDay:30},title:"सकिमना पुन्ही",content:[{type:"paragraph",text:'कार्तिक शुक्ल पूर्णिमाका दिन नेवार समुदायले मनाउने यो पर्वमा पिँडालु (सकि) उसिनेर खाने चलन छ। यसलाई "पिँडालु उबाउने पूर्णिमा" पनि भनिन्छ। यो शरीरलाई जाडोको लागि तयार गर्ने खानपानको पर्व हो।'},{type:"heading",text:"हलिं विलिं"},{type:"paragraph",text:"यस दिन भक्तपुर र कीर्तिपुरका केही स्थानमा भुटेको मकै र गहुँले मन्दिर वा देवताको तस्बिर बनाउने कला (हलिं विलिं) प्रदर्शन गरिन्छ, जुन अत्यन्त आकर्षक हुन्छ।"},{type:"list",items:["पिँडालु खाने","हलिं विलिं कला","नसंचा (भजन)","मन्दिर दर्शन"]}]},{id:"p35",eventDate:{type:"LUNAR",month:7,paksha:"shukla",tithi:11,approxBsDay:26},title:"माईपोखरी मेला (इलाम)",content:[{type:"paragraph",text:"इलाम जिल्लाको प्रसिद्ध रामसार क्षेत्र माईपोखरीमा हरिबोधिनी एकादशीको दिन ठूलो मेला लाग्छ। नौ वटा कुना भएको यो पोखरीमा नौवटै देवीको बास रहेको विश्वास गरिन्छ।"},{type:"image",src:t.maiPokhari,alt:"Mai Pokhari"},{type:"heading",text:"धार्मिक आस्था"},{type:"paragraph",text:"यहाँ सत्य मनले पूजा गरेमा सन्तान प्राप्ति हुने र रोगव्याधि हट्ने जनविश्वास छ। यो किराँत, हिन्दु र बौद्ध धर्मालम्बीहरूको साझा तीर्थस्थल हो।"},{type:"list",items:["पोखरी परिक्रमा","धार्मिक पूजा","जैविक विविधता अवलोकन","वरदान माग्ने"]}]},{id:"p36",eventDate:{type:"LUNAR",month:5,paksha:"krishna",tithi:2,approxBsDay:17},title:"नीलबाराही जात्रा",content:[{type:"paragraph",text:"भक्तपुरको बोडेमा मनाइने यो जात्रा तान्त्रिक विधिमा आधारित छ। यो भाद्र द्वितीयादेखि ४ दिनसम्म चल्छ। यसमा १९ जना देवगणहरू (देवताको भेषमा मानिसहरू) दिनरात नसुती नाच्छन्।"},{type:"heading",text:"दैवी शक्ति"},{type:"paragraph",text:"देवताको मुखुन्डो लगाएपछि मानिसमा दैवी शक्ति आउने र उनीहरू काप्न थाल्ने बताइन्छ। यो जात्रा हेर्न र देवताको आशीर्वाद लिन ठूलो भीड लाग्छ।"},{type:"list",items:["तान्त्रिक नाच","देवगणको परिक्रमा","मुखुन्डो प्रदर्शन","जाग्राम"]}]},{id:"p37",eventDate:{type:"LUNAR",month:1,paksha:"shukla",tithi:15,approxBsDay:30},title:"चण्डेश्वरी जात्रा",content:[{type:"paragraph",text:"काभ्रेको बनेपामा वैशाख पूर्णिमाको दिन मनाइने सबैभन्दा ठूलो जात्रा हो। चण्डासुर नामक राक्षसलाई देवी चण्डेश्वरीले वध गरेको खुसीयालीमा यो मनाइन्छ।"},{type:"image",src:t.chandeshwari,alt:"Chandeshwari Temple"},{type:"heading",text:"कलँदा बाजा"},{type:"paragraph",text:'रथलाई बोकेर (तानेर होइन) सहर परिक्रमा गराइन्छ। "कलँदा" भनिने विशेष बाजा बजाउँदै र प्रसादको रूपमा मासुको परिकार (छोयला) बाँड्दै यो जात्रा उल्लासका साथ मनाइन्छ।'},{type:"list",items:["रथ बोक्ने","कलँदा बाजा वादन","छोयला प्रसाद","राक्षस वध उत्सव"]}]},{id:"p38",eventDate:{type:"LUNAR",month:1,paksha:"shukla",tithi:3,approxBsDay:18},title:"लुभु जात्रा",content:[{type:"paragraph",text:"ललितपुरको लुभु गाउँमा वैशाख शुक्ल अक्षय तृतीयाको आसपास महालक्ष्मी-महाभैरवको भव्य जात्रा मनाइन्छ। यहाँका बासिन्दाले महालक्ष्मीलाई आमाको रूपमा पुज्छन्।"},{type:"heading",text:"रथ जुधाउने"},{type:"paragraph",text:"दुईवटा रथ (महालक्ष्मी र भैरव) लाई एकैपटक नचाउँदै नगर परिक्रमा गराइन्छ। नेवार समुदायको टेक्सटाइल (कपडा बुन्ने) नगरीको रूपमा चिनिने लुभुमा यो समयमा विशेष चहलपहल हुन्छ।"},{type:"list",items:["द्वय रथयात्रा","महालक्ष्मी पूजा","छत्र पूजा","भोजभतेर"]}]},{id:"p39",eventDate:{type:"LUNAR",month:1,paksha:"shukla",tithi:14,approxBsDay:29},title:"नृसिंह जयन्ती",content:[{type:"paragraph",text:"वैशाख शुक्ल चतुर्दशीका दिन भगवान विष्णुले आधा मानिस र आधा सिंह (नृसिंह) को रूप धारण गरी दैत्यराज हिरण्यकश्यपको वध गरेको दिन हो। भक्त प्रह्लादको रक्षाका लागि खम्बा फोडेर भगवान प्रकट हुनुभएको थियो।"},{type:"heading",text:"अधर्मको नाश"},{type:"paragraph",text:'यो दिनले "जतिसुकै शक्तिशाली भए पनि अधर्मको अन्त्य निश्चित छ" भन्ने सन्देश दिन्छ। वैष्णव मन्दिरहरूमा विशेष पूजा, भजन र उपवास बस्ने चलन छ।'},{type:"list",items:["विष्णु पूजा","नृसिंह कथा","उपवास","भजन कीर्तन"]}]},{id:"p40",eventDate:{type:"BS",month:3,day:7,approxBsDay:7},title:"अन्तर्राष्ट्रिय योग दिवस",content:[{type:"paragraph",text:'जुन २१ (असार महिना) लाई विश्वभरि अन्तर्राष्ट्रिय योग दिवसका रूपमा मनाइन्छ। योगको उद्गमस्थल नेपाल र भारत क्षेत्र भएकाले नेपालमा यसको विशेष महत्त्व छ। "योग" भनेको आत्माको परमात्मासँग जोडिनु हो।'},{type:"image",src:t.yogaDay,alt:"Yoga Day"},{type:"heading",text:"स्वस्थ जीवन"},{type:"paragraph",text:"प्रधानमन्त्री, मन्त्रीहरूदेखि सर्वसाधारणसम्मले बिहानै सामूहिक रूपमा योगासन, प्राणायाम र ध्यान गर्छन्। स्वस्थ जीवनशैली अपनाउन प्रेरित गर्ने यो आधुनिक समयको महत्त्वपूर्ण दिवस हो।"},{type:"list",items:["सामूहिक योगासन","प्राणायाम र ध्यान","आरोग्य चर्चा","अन्तर्राष्ट्रिय ऐक्यबद्धता"]}]}],r=a,s=p,y=n,h=i,g=a,x=p,o=n,l=i,k=e=>e==="en"?r:e==="hi"?g:a,B=e=>e==="en"?s:e==="hi"?x:p,R=e=>e==="en"?y:e==="hi"?o:n,N=e=>e==="en"?h:e==="hi"?l:i;export{N as getChadparbaData,B as getMantraData,k as getPujaData,R as getStotraData};
